insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('decision', 'beginner', 'module', 'm01-what-a-decision-tree-is', 1, 'On the EKPAN tree the dry hole is the single most likely outcome at 0.500000, and in a dry hole the farm-out''s 0.0000 beats the drill''s -25.0000. An owner farms out on that ground. What does the tree say about the choice?', '["It agrees with the choice, because a decision node takes the branch that does best in the outcome carrying the largest probability.", "It trades a branch worth 105.0000 for one worth 37.7500, because the tree weights every outcome by its probability and the drill pays far more in the other half.", "It agrees once the drill cost of 55.0000 is charged, because the drill then loses money in the most likely outcome and a decision node avoids a likely loss.", "It cannot judge the choice, because a risk neutral engine gives no weight to how likely any single outcome is when it compares the moves."]'::jsonb, 1, 'Choosing by the most likely outcome ignores the probability where the drill pays 420.0000 or 170.0000. Weighted, the drill branch is worth 105.0000 against the farm-out''s 37.7500.'),
  ('decision', 'beginner', 'module', 'm01-what-a-decision-tree-is', 2, 'On the EKPAN tree, "Marginal find" sits under the drill''s chance node. What kind of node is it, and what does the chance node weight for it?', '["A terminal paying the develop payoff of 260.0000, weighted at 0.150000 like the success and the dry hole beside it.", "A chance node between Develop and Sell, entering the weighting at an average of their values because the owner cannot know which will follow.", "A decision node, entering the weighting at the sale''s 140.0000, since a choice made after drilling is valued at its safer branch.", "A decision node, entering the weighting at its best branch value of 170.0000."]'::jsonb, 3, 'The owner chooses only if a marginal find occurs, and takes the better branch: Develop at 260.0000 less 90.0000, which is 170.0000, against Sell at 140.0000.'),
  ('decision', 'beginner', 'module', 'm01-what-a-decision-tree-is', 3, 'The Decision Tree Builder''s drawing labels the EKPAN tree''s drill chance node EMV 160, while the drill branch and the root are worth 105.0000. Why do the two differ?', '["The label is the node''s own value, before the drill cost of 55.0000 on the branch leading into it.", "The label is the drill value before discounting, and 105.0000 is it after the rollback''s rate.", "The label rounds a value above 100 to no decimals, which opens the gap to 105.0000.", "The label weights the marginal find at its develop payoff of 260.0000, where the branch value uses the develop branch value instead."]'::jsonb, 0, 'The drill node weights its outcomes to 160.0000, and the branch subtracts 55.0000 once to give 105.0000. The number to set against the farm-out''s 37.7500 is the branch value.'),
  ('decision', 'beginner', 'module', 'm01-what-a-decision-tree-is', 4, 'A chance node''s probabilities are typed so that they sum to 0.9. What does the engine return?', '["The EMV of the node with its probabilities rescaled so they sum to 1, and a warning naming the node beside the result.", "The EMV computed on the probabilities as typed, carrying only 0.9 of the weight, since the sum check warns and does not stop the rollback.", "A refusal naming the node and printing the sum 0.900000, with no EMV for any part of the tree.", "An EMV for every node except the one that failed, which is carried up the tree as a value of zero so the root can still be compared."]'::jsonb, 2, 'The engine checks the sum and never repairs it. The published message reads Chance branch probabilities sum to 0.900000, expected 1, at node bad, and a refusal returns no EMV at all.'),
  ('decision', 'beginner', 'module', 'm01-what-a-decision-tree-is', 5, 'The published rollbackRefusals cases include a chance node with one branch typed at probability 1.5. What does the engine return for it?', '["An EMV with that branch clamped to 1 and the rest set to zero.", "A refusal saying branch a needs a probability between 0 and 1, at node bad.", "A refusal printing the node''s sum, found as the branches are added.", "An EMV weighted on the typed numbers, since a branch above 1 is legal whenever another branch on the node is typed low enough to balance it."]'::jsonb, 1, 'The message names the branch and the node: Branch a needs a probability between 0 and 1, at node bad. The engine never clamps a probability of 1.5 into range.'),
  ('decision', 'beginner', 'module', 'm01-what-a-decision-tree-is', 6, 'A company will not accept an even chance of losing 80.0000 million USD. What can it set in the engine so that the EKPAN tree prefers the farm-out?', '["A risk aversion parameter on the root decision, which penalises each branch by its chance of losing money before the maximum is taken.", "The dry hole''s probability of 0.500000, which the engine reads a second time as a loss weight after the rollback has finished.", "The listing order, typing the farm-out first so that the tie rule hands it the root.", "Nothing: neither the tree engine nor the VOI Analyzer has a utility function or a risk aversion parameter."]'::jsonb, 3, 'The rollback maximises expected money, so the drill at 105.0000 beats the farm-out at 37.7500 however badly the drill''s -80.0000 hurts. Listing order decides only exact ties, and 105.0000 against 37.7500 is none.'),
  ('decision', 'beginner', 'module', 'm01-what-a-decision-tree-is', 7, 'On the EKPAN tree, the develop cost of 90.0000 is spent only after the well has found something, years after the root decision. What must be true of it and of its 260.0000 payoff?', '["Both must already be present values at the date and rate of the root decision, because the rollback adds them at face value.", "Only the payoff must be discounted by hand, as the engine discounts a cost by how deep its branch sits.", "Nothing, because a cost is charged before a chance node weights it, which already places it on the date of the root decision.", "Both must be typed as undiscounted cash, as the engine applies one rate to every payoff and cost."]'::jsonb, 0, 'The engine has no rate and no dates: 420.0000, -25.0000 and the drill cost of 55.0000 enter exactly as typed. Whatever valued the numbers must have put them on one date.'),
  ('decision', 'beginner', 'module', 'm01-what-a-decision-tree-is', 8, 'An analyst applies a discount rate by hand to an NPV that is already discounted, then types the result as a terminal payoff. What happens to the tree?', '["The engine detects the second discount and refuses the terminal with the message Distribution payoff has no finite mean.", "Nothing changes, because the rollback strips any rate applied to a payoff before it weights the payoff at its chance node.", "Every payoff shrinks while costs stay put, pulling the choice toward the cheaper branch, and nothing in the output shows it.", "Payoffs and costs shrink alike, so the EMV falls in proportion and the recommended branch can never change as a result."]'::jsonb, 2, 'The engine adds numbers at face value, so a smaller 420.0000 meets an unchanged cost of 55.0000. Neither discounting twice nor not at all leaves any trace in the output.'),
  ('decision', 'beginner', 'module', 'm01-what-a-decision-tree-is', 9, 'A Builder terminal on a tree is linked to a saved Monte Carlo run, and the run is later revalued. What does the tree use for that terminal?', '["The revalued run, because the Builder re-reads every linked run each time the tree is rolled back and replaces the stored numbers.", "The copy of the run''s NPV mean, P90 and P10 stored when it was linked, until the terminal is linked again.", "A refusal, Distribution payoff has no finite mean, until the changed run is linked again.", "The revalued P10 and P90 beside the old mean, since only the mean is copied at linking and the percentiles are read live from the run."]'::jsonb, 1, 'Linking stores a copy in million USD at that moment and nothing re-reads the run, so a tree rolled back to 105.0000 on a stale copy gives no warning. Unlinking keeps the mean as a fixed payoff.'),
  ('decision', 'beginner', 'module', 'm01-what-a-decision-tree-is', 10, 'On the published equalEmvTie case, branches A and B are both worth 30.0000 and C is worth 29.9990, and the engine returns A. Listed with B first, what does it return?', '["B, at the same EMV of 30.0000, because a later branch replaces the current best only when strictly greater.", "A, because the engine sorts a decision node''s branches by name before it compares their values.", "No recommendation, because an exact tie is refused as ambiguous with a message naming the node.", "C, because 29.9990 lies within the engine''s tolerance of 30.0000 and the last near tie listed is kept."]'::jsonb, 0, 'Equal never displaces earlier, so the first of the tied branches keeps the root at 30.0000. In a tie the recommendation records the order of typing and nothing about the branches.'),
  ('decision', 'beginner', 'module', 'm01-what-a-decision-tree-is', 11, 'A tree with undiscounted payoffs, a success probability chosen to flatter the drill and conveniently ordered branches rolls back with no error. What does the absence of an error establish?', '["That its payoffs are present values, since the engine refuses a terminal typed without a rate.", "That no branch left off the tree would have beaten the best, since each decision node is checked for a walk-away before it is accepted.", "That its probabilities describe the prospect, since a probability chosen to favour one branch would push its chance node out of tolerance.", "Only that the tree is well formed: known node types, at least one branch per node and probability sums within 1e-6 of 1."]'::jsonb, 3, 'The engine checks shape, never truth. Any set of probabilities that sums to 1 within 1e-6 passes, and the EKPAN tree''s 105.0000 is only as good as its inputs.'),
  ('decision', 'beginner', 'module', 'm01-what-a-decision-tree-is', 12, 'An owner picks the drill on the EKPAN tree because its success pays 420.0000, the largest number in the table. What is wrong with that reasoning, given that the tree also recommends Drill?', '["Nothing is wrong with it, because a decision node takes the branch holding the largest single payoff anywhere beneath it.", "It reads the payoff before the drill cost, and 420.0000 less 55.0000 would lose to the farm-out once both are compared.", "It never uses the probabilities, so it would pick the drill just as confidently at a success chance too low to justify it.", "It uses the success outcome, which is the least likely of the three, where the tree takes the outcome with the largest probability."]'::jsonb, 2, 'The tree weights 0.350000 x 420.0000 + 0.150000 x 170.0000 + 0.500000 x -25.0000 = 160.0000 and then subtracts 55.0000. The best case alone picks the drill for the wrong reason.'),
  ('decision', 'beginner', 'module', 'm01-what-a-decision-tree-is', 13, 'A branch on a tree is typed with no child node beneath it. What does the engine return?', '["A branch value of zero, the absent child read as a terminal that pays nothing, so the rest of the tree still rolls back.", "The refusal Missing node, with no EMV for the tree.", "The refusal Unknown node type, since an absent child has no type among the three the engine recognises.", "A branch worth minus its own cost, since a cost is charged when the branch is taken whatever lies below it."]'::jsonb, 1, 'The engine never guesses what a malformed node meant. A missing child is refused, and a node typed lottery is refused separately as Unknown node type; neither returns a value in place of 105.0000.'),
  ('decision', 'beginner', 'module', 'm01-what-a-decision-tree-is', 14, 'At the EKPAN tree''s root decision node, which three numbers does the engine compare?', '["105.0000, 37.7500 and 0.0000, each the child''s value less the cost on its branch.", "160.0000, 37.7500 and 0.0000, the nodes'' own values, with the drill cost of 55.0000 charged once the maximum has been taken.", "420.0000, 95.0000 and 0.0000, the best payoff reachable on each branch.", "-25.0000, 0.0000 and 0.0000, the worst outcome each branch can deliver, since the root guards against a loss."]'::jsonb, 0, 'Nodes combine branch values, never raw child values: the drill''s chance node is 160.0000 and its branch 105.0000. The root takes the largest, EMV 105.0000, best branch index 0.'),
  ('decision', 'beginner', 'module', 'm01-what-a-decision-tree-is', 15, 'A decision node picks one of its branches. What does a chance node on the EKPAN tree pick?', '["The most likely branch, the dry hole at 0.500000, passed up unweighted.", "The best branch, as a decision node would, with its probability noted.", "Only the branches that are on the optimal path, which it weights by their probabilities rescaled to sum to 1.", "None: it uses every branch, weighting each branch value by its probability."]'::jsonb, 3, 'The drill outcome node uses all three: 0.350000 x 420.0000 + 0.150000 x 170.0000 + 0.500000 x -25.0000 = 160.0000. Only a decision node takes a maximum.'),
  ('decision', 'beginner', 'module', 'm02-chance-nodes', 1, 'Weighting the EKPAN tree''s marginal find at 260.0000 gives a drill chance node that is not 160.0000, and the engine accepts it without complaint. What has that calculation got wrong?', '["It treats the marginal find as a decision, when the owner has no further choice once a marginal accumulation is found and must simply develop it at 260.0000.", "It weights the payoff before discounting it, when the engine expects the develop cost of 90.0000 to be applied to the 260.0000 payoff as a discount rate.", "It treats development as free, reading the develop payoff where the node needs the develop branch value of 170.0000 after its 90.0000 cost.", "It counts the drill cost of 55.0000 twice, since the develop payoff of 260.0000 already has the drill cost taken out of it."]'::jsonb, 2, 'A chance node weights branch values. Develop is 260.0000 less 90.0000, which is 170.0000, and it beats Sell at 140.0000; the probabilities are untouched, so the engine has nothing to refuse.'),
  ('decision', 'beginner', 'module', 'm02-chance-nodes', 2, 'A chance node with three equal outcomes paying 30, 60 and 90 has each probability typed as 0.333333. What does the engine return?', '["A refusal printing the sum 0.999999, because a sum sitting at the edge of the 1e-6 tolerance is not accepted.", "EMV 60.0000, since 0.999999 is within 1e-6 of 1 and the check is inclusive at its edge.", "EMV 60.0000 from the weights rescaled to sum to 1, with the typed sum printed as a warning.", "EMV 35.0000, the published thirdsProbabilities result, since that case types its thirds to six decimals."]'::jsonb, 0, 'Seven decimals, 0.3333333 each, are accepted at EMV 60.0000; six decimals print 0.999999 and are refused. The thirdsProbabilities case is a different tree whose 35.0000 matches its own golden.'),
  ('decision', 'beginner', 'module', 'm02-chance-nodes', 3, 'Refused with thirds typed at 0.333 each, a reader adds the whole shortfall to the last branch of the node paying 30, 60 and 90. What does that produce?', '["A second refusal, since the engine checks that branches typed as thirds still carry equal probabilities before it weights any of them.", "An accepted tree at EMV 60.0000 exactly, since the sum is now 1 and moving weight between the branches cannot move the mean of 30, 60 and 90.", "An accepted tree at EMV 60.0000, because the engine spreads a shortfall added to one branch evenly back over all three branches before weighting.", "An accepted tree whose last outcome now carries more weight than the other two, although the three were meant to be equal."]'::jsonb, 3, 'The engine checks only the sum, 0.999000 as first typed, and never whether the weights are the intended ones. The fix is to type every branch at enough precision, as 0.3333333 each rolls back to 60.0000.'),
  ('decision', 'beginner', 'module', 'm02-chance-nodes', 4, 'One chance node two levels below the root of a tree sums to 0.2, and every other node is well formed. What does the engine return for the well formed parts?', '["Their EMVs, since the sum is checked only at chance nodes directly beneath the root decision.", "No EMV for any of them: the whole tree is refused, and the message names the failing node cc and prints 0.200000.", "Their EMVs, with the failing node carried up the tree at zero so that the root can still be compared.", "The root''s EMV with the failing node rescaled to sum to 1, and a warning naming node cc beside it."]'::jsonb, 1, 'The check runs at every chance node however deep, so a sum of 0.200000 two levels down refuses the tree and returns nothing. Leaving an outcome off a node is refused the same way: the engine never spreads a missing probability over the rest.'),
  ('decision', 'beginner', 'module', 'm02-chance-nodes', 5, 'On the published chanceRootWithBranchCosts tree, calm has probability 0.600000, cost 2.0000 and child 19.0000, and storm has probability 0.400000, cost 8.0000 and child -25.0000. What is the root EMV?', '["-8.6000, from the two children weighted first and both costs, 2.0000 and 8.0000, subtracted once afterwards.", "17.0000, the calm branch value, since a root that is a chance node keeps its likelier branch.", "-3.0000, from branch values of 17.0000 and -33.0000 weighted by 0.600000 and 0.400000.", "-33.0000, the storm branch value, since a chance root with no move to make reports its worst branch."]'::jsonb, 2, 'Each branch value is its child less its own cost, and only then does the node weight: 0.600000 x 17.0000 + 0.400000 x -33.0000 = -3.0000.'),
  ('decision', 'beginner', 'module', 'm02-chance-nodes', 6, 'A reader collects every cost on the chanceRootWithBranchCosts tree into one total and subtracts it after weighting, the way a budget would, and gets -8.6000. Why is that wrong?', '["It is flagged by the engine, which refuses any cost placed on a branch below a chance node and points to the root instead.", "It discounts both costs to a later date, since a cost charged after weighting is treated as paid once the outcome is known.", "It is right at the root and wrong at the branches, since a chance root is worth the same whichever way its costs are charged.", "It charges the storm cost in the calm and the calm cost in the storm, money for events that did not occur."]'::jsonb, 3, 'A cost on a branch is paid only on that branch. The difference between -3.0000 and -8.6000 is money charged for outcomes that never happened, and a hand calculation is never refused.'),
  ('decision', 'beginner', 'module', 'm02-chance-nodes', 7, 'What do the Decision Tree Builder''s cards show for the chanceRootWithBranchCosts tree, whose root is a chance node?', '["Optimal EMV -3.0000, Chance root on the first-move card, and N/A on the next best alternative and decision advantage cards.", "Calm as the recommended first move, being the likelier branch at 0.600000, with storm as the next best alternative and a decision advantage beside it.", "No cards, since the Builder needs a decision at the root and refuses to roll back a tree whose root is a chance node.", "Optimal EMV -8.6000, since the Builder subtracts the tree''s costs once after the rollback to fill the card."]'::jsonb, 0, 'The cards assume a decision at the root. Facing that chance is worth -3.0000, and there is no move to recommend or compare.'),
  ('decision', 'beginner', 'module', 'm02-chance-nodes', 8, 'The EKPAN tree''s success payoff of 420.0000 is replaced by a linked NPV summary with mean 420, P90 185, P50 390 and P10 710, and the tree still rolls back to 105.0000. Why does the spread move nothing?', '["The engine sets the P90 of 185 against the P10 of 710 as a risk adjustment, and for this particular summary their two pulls on the payoff cancel out.", "A chance node is linear in its payoffs, so the mean alone gives the expected value and the rest of the summary cannot change it.", "It does move it, and 105.0000 is the P50 case once the Builder''s drawing has rounded the node label.", "The spread enters the rollback only at decision nodes, as a risk adjustment on the branch taken, and the success terminal hangs below a chance node."]'::jsonb, 1, 'Averaging over the summary before or after weighting by 0.350000 gives the same number, so a success worth exactly 420.0000 and one spread from 185 to 710 produce the same 105.0000.'),
  ('decision', 'beginner', 'module', 'm02-chance-nodes', 9, 'To be conservative, an analyst types the summary''s P90 of 185 as the EKPAN tree''s success payoff instead of its mean. What does the tree then report?', '["The drill branch rises to 206.5000, because under the exceedance meaning a P90 is the high case of the summary.", "The EMV stays at 105.0000, since the engine reads a linked payoff at its mean whatever statistic is typed in.", "The drill branch falls to 94.5000 and still wins, because a P90 moves a payoff less than a P50 would.", "The drill branch falls to 22.7500, below the farm-out''s 37.7500, so the tree recommends the farm-out at an EMV that is not the drill''s value."]'::jsonb, 3, 'P90 is the low case. Read there, the drill weighting gives 22.7500 and the root takes Farm out at 37.7500, which turns a risk preference into what looks like an expected value.'),
  ('decision', 'beginner', 'module', 'm02-chance-nodes', 10, 'A summary typed as a terminal payoff carries a P90 of 185, a P50 of 390 and a P10 of 710, and no mean. What does the engine return?', '["A refusal, Distribution payoff has no finite mean, since the engine does not estimate a mean from the percentiles.", "An EMV using the P50 of 390 as the payoff, since the middle of the distribution stands in for a mean the summary does not carry.", "An EMV using the midpoint of the P90 and the P10 as its estimate of the mean, printed with a warning.", "An EMV of 105.0000, from the mean last stored for that terminal when a run was linked to it."]'::jsonb, 0, 'Only the mean enters the rollback, so a summary without one gives the engine nothing to weight. It refuses rather than guessing from 185, 390 and 710.'),
  ('decision', 'beginner', 'module', 'm02-chance-nodes', 11, 'An analyst types the linked summary''s P50 of 390 as the EKPAN tree''s success payoff, because it is the middle of the distribution. What does the tree return?', '["EMV 105.0000, since the P50 and the mean coincide for every summary the Builder can link from a saved Monte Carlo run.", "EMV 94.5000 with Drill, below the true 105.0000, because a chance node needs the mean and the P50 is not it.", "EMV 37.7500 with Farm out, since reading any percentile in place of the mean flips the EKPAN tree.", "EMV 206.5000 with Drill, since under the exceedance meaning a P50 sits above the mean of the summary."]'::jsonb, 1, 'At 390 the drill weighting gives a branch value of 94.5000. It still beats the farm-out''s 37.7500 here, and on a closer choice that shortfall could flip the move.'),
  ('decision', 'beginner', 'module', 'm02-chance-nodes', 12, 'An owner drills EKPAN once. Which statement about that single well on the EKPAN tree is true?', '["It leaves 105.0000 on average each time, since the branch value is the most likely money the drill returns.", "It loses money with probability 0.650000, the dry hole chance that the drill carries on EKPAN.", "It leaves 365.0000, 115.0000 or -80.0000 after the drill cost, loses money with probability 0.500000, and never leaves 105.0000.", "It leaves 420.0000, 170.0000 or -25.0000, since the drill cost of 55.0000 is already inside the chance node''s value of 160.0000 and is not charged again."]'::jsonb, 2, '105.0000 is an average over outcomes, and the owner receives one of them. 0.650000 is the dry hole of the EKPAN lottery, a different two-outcome model, and mixing it in is exactly the error; the EKPAN tree''s dry hole is 0.500000.'),
  ('decision', 'beginner', 'module', 'm02-chance-nodes', 13, 'A report says that on the EKPAN tree the marginal find, which leaves 115.0000 after the drill cost, is a little above expectation. What is wrong with that sentence?', '["Nothing is wrong, because the outcome closest to the EMV is by definition the expected case of the chance node.", "The marginal find really leaves 60.0000 once the drill cost of 55.0000 is taken off 115.0000, which is below expectation.", "The comparison should be with 160.0000, the drill node''s EMV, which is the expectation the drawing prints for the well.", "It treats the EMV as a middle case, when 105.0000 is a weighted average pulled up by the 365.0000 success and need not sit near any outcome."]'::jsonb, 3, 'The marginal find happens with probability 0.150000. 115.0000 is already net of the drill cost, so subtracting 55.0000 again counts it twice, and 160.0000 is a value before that cost.'),
  ('decision', 'beginner', 'module', 'm02-chance-nodes', 14, 'A programme is sized on the EKPAN tree''s EMV of 105.0000. What does the rollback itself report that could warn against it?', '["Nothing: it returns values and best branches, with no distribution, chance of loss or worst case for any branch.", "The Optimal EMV card, which prints the chance of loss beside the root EMV when a branch can lose.", "The onOptimalPath flags, which mark the dry hole false because it loses money on the drill branch that the rollback has chosen.", "The drawing''s EMV 160 label on the drill node, which is the money the well returns before any loss from a dry hole is counted."]'::jsonb, 0, 'The drill''s half chance of leaving -80.0000 is worked by hand. The dry hole is flagged true, because choosing to drill means facing it.'),
  ('decision', 'beginner', 'module', 'm02-chance-nodes', 15, 'Weighting the drill''s after-cost money on the EKPAN tree, 365.0000, 115.0000 and -80.0000, by 0.350000, 0.150000 and 0.500000 returns what, and why?', '["160.0000, the drill chance node, because weighting a branch''s outcomes always returns the node value from before the cost on its branch.", "105.0000, the branch value, because the probabilities sum to 1, so taking 55.0000 off every outcome takes it once off the average.", "50.0000, because the drill cost of 55.0000 is charged on the branch again once the weighting is done.", "105.0000 by coincidence of these payoffs, since a cost taken off each outcome is weighted by probabilities that need not add up to exactly 1."]'::jsonb, 1, 'Weighted, the three after-cost amounts reproduce the rollback''s 105.0000, and the branch value is not among them. Charging 55.0000 again after the weighting would count the cost twice.'),
  ('decision', 'beginner', 'module', 'm03-decision-nodes', 1, 'On the EKPAN tree the Builder shows Optimal EMV 105.0000, Recommended first move Drill, Next best alternative 37.7500 and Decision advantage 67.2500. What does the advantage measure?', '["The money the drill makes over the farm-out on the one well drilled, since both moves face the same outcome.", "The drill node''s value less the farm-out''s, read off the drawing''s node labels before the drill cost is charged.", "The drill''s lead over the farm-out in only the outcomes where it does better, weighted across the 0.500000 of the probability that is not a dry hole.", "The EMV given up by taking the farm-out instead of the drill, a difference of averages that says nothing about how often the drill does worse."]'::jsonb, 3, 'The advantage is 105.0000 less 37.7500. The drill still leaves -80.0000 half the time while the farm-out never loses, and no card shows that.'),
  ('decision', 'beginner', 'module', 'm03-decision-nodes', 2, 'Inside the EKPAN tree''s drill, a reader compares Develop at 260.0000 with Sell at 140.0000 and picks Develop. What has the comparison got wrong?', '["It finds the wrong branch, since Sell at 140.0000 beats Develop once the develop cost of 90.0000 has been paid.", "It finds the right branch at a value 90.0000 too high, and that inflated value would then be weighted into the drill node.", "Nothing, since a decision node compares payoffs, and only a chance node needs branch values net of their costs.", "Nothing, since a cost on a branch below a chance node is charged at the drill branch above it, alongside the 55.0000, rather than where it sits."]'::jsonb, 1, 'A decision node only ever compares branch values: Develop is 260.0000 less 90.0000, which is 170.0000, against Sell''s 140.0000. The drill chance node weights 170.0000.'),
  ('decision', 'beginner', 'module', 'm03-decision-nodes', 3, 'On the EKPAN tree, the drill''s dry hole reads onOptimalPath true while the farm-out''s success reads false. Why?', '["Every branch of a chance node on the path is on it, so drilling means facing the dry hole, while the farm-out''s outcomes lie below a branch not taken.", "The dry hole is the most likely outcome at 0.500000, and the farm-out''s success at 95.0000 pays less than the root EMV.", "The engine flags the outcomes of whichever chance node has the larger own value, and the drill''s node at 160.0000 beats the farm-out''s 37.7500.", "The flags mark losses the owner has to insure against, and the farm-out''s success is not a loss at any probability."]'::jsonb, 0, 'Farm out lost at the root, 37.7500 against 105.0000, so nothing beneath it is reached. The dry hole at -25.0000 is on the path because the plan to drill has to answer it.'),
  ('decision', 'beginner', 'module', 'm03-decision-nodes', 4, 'On the EKPAN tree, Sell under the marginal find reads onOptimalPath false. Which reading of that flag is right?', '["Sell is a poor outcome, since a false flag marks a branch whose value falls below the root EMV of 105.0000.", "Sell can never be reached, because the marginal find itself sits off the optimal path beneath the drill''s chance node and so is never faced.", "Develop is better there, 170.0000 against 140.0000, and Sell would be off the path anyway had the owner not drilled.", "Sell loses money once the drill cost of 55.0000 is charged against its 140.0000 as well, and a false flag is how the engine records that loss."]'::jsonb, 2, 'A false flag says a branch is not reached under the best strategy, not that it is poor: Sell''s 140.0000 is above 105.0000 and still off the path because Develop wins at 170.0000.'),
  ('decision', 'beginner', 'module', 'm03-decision-nodes', 5, 'Drill pays 40.0000 at a cost of 10.0000 and Farm out pays 30.0000. The same two branches are typed once with Drill first and once with Farm out first. What does the engine return?', '["Drill in both orders, since the engine compares children before their costs and Drill''s 40.0000 is the larger.", "Drill when Drill is listed first and Farm out when Farm out is listed first, both at EMV 30.0000.", "Farm out in both orders, since a branch with no cost wins an exact tie against a branch that carries one.", "A refusal in both orders, since two branches of exactly equal value leave the decision node without a best branch."]'::jsonb, 1, 'Drill''s branch value is 40.0000 less 10.0000, which is 30.0000, exactly Farm out''s. A later branch displaces an earlier one only by being strictly greater, so the order of typing names the move.'),
  ('decision', 'beginner', 'module', 'm03-decision-nodes', 6, 'At a success probability of 0.228571, the EKPAN lottery (the two-outcome model, not the EKPAN tree) prints Drill 21.7143 and Farm out 21.7143 and names Farm out, the second branch. Why?', '["The tie rule, which on an exact tie keeps the branch carrying no cost rather than the branch that is listed first.", "The tie rule, which keeps the last branch listed when two values print as equal to four decimals.", "The engine rounds branch values to four decimals before comparing, and breaks the printed tie toward the safer branch.", "The crossing has no exact binary image, so the values differ in their last binary digits and Farm out is larger by that residue; the tie rule plays no part."]'::jsonb, 3, 'Only an exact tie goes to the first branch. Two values printed as 21.7143 can be unequal, and the engine chooses between them without any tie involved.'),
  ('decision', 'beginner', 'module', 'm03-decision-nodes', 7, 'The published drillFarmOut tree, with its success probability swept, reads Drill 12.0000 and Farm out 12.0000 at 0.200000, and the engine reports Drill. Which reading is right?', '["Drill is named at 0.200000 only because it is listed first; Farm out leads at 0.150000, 9.0000 to -3.5000, and Drill leads at 0.250000, 27.5000 to 15.0000.", "Drill is named because its value is larger in the last binary digits, the same residue that names Farm out on the EKPAN lottery.", "Drill is named because a branch that carries a cost wins an exact tie against one that pays out without any cost.", "Farm out should have been named, since the engine keeps the branch that led at the lower probability of 0.150000."]'::jsonb, 0, 'This is an exact tie, 12.0000 against 12.0000, so the strictly greater rule keeps the first branch. The EKPAN lottery''s crossing is a different case, a rounding residue, and borrowing that explanation here is the mistake examined.'),
  ('decision', 'beginner', 'module', 'm03-decision-nodes', 8, 'Which plan states the EKPAN tree''s optimal strategy?', '["Drill; on a success take 420.0000; on a marginal find sell for 140.0000, the safer later choice; on a dry hole accept -25.0000.", "Drill and take 420.0000, since the optimal path is the single line from the root down to the best payoff.", "Drill; on a success take 420.0000; on a marginal find develop; on a dry hole accept -25.0000.", "Drill; on a marginal find develop; on a dry hole farm out instead for 0.0000 rather than accept the -25.0000."]'::jsonb, 2, 'The path runs through one branch at each decision reached and every branch of each chance node on it, so it covers the dry hole at 0.500000. The farm-out is a root alternative, not a move available after drilling.'),
  ('decision', 'beginner', 'module', 'm03-decision-nodes', 9, 'The published allNegative case has branches A at -55.0000 and B at -52.0000. What does the Builder show, and what does it mean?', '["No recommendation, since a decision node refuses a root whose best branch value is below zero.", "B as the first move at Optimal EMV -52.0000 with an advantage of 3.0000, and nothing on the cards says both moves lose money.", "A walk-away at 0.0000, which the engine adds to any decision node whose branches all lose money.", "A at -55.0000, since a decision node takes the branch whose value is largest in size regardless of its sign, and 55 is larger than 52."]'::jsonb, 1, 'The rule is the maximum over the branches drawn, and -52.0000 is larger than -55.0000. The advantage of 3.0000 is only the gap between two losses, and says nothing about whether either move should be taken.'),
  ('decision', 'beginner', 'module', 'm03-decision-nodes', 10, 'If a walk-away branch at 0.0000 were added to the published allNegative tree, what would its root read, and why could the engine not reach that on its own?', '["B at -52.0000 unchanged, since a walk-away branch only competes at a decision node that also has a chance node beneath it for the walk-away to protect against.", "The walk-away at 0.0000, which the engine had already chosen silently, because it floors every decision at zero.", "A refusal, since a walk-away at 0.0000 drawn beside branches that all lose money makes the decision node''s values inconsistent with one another in sign.", "EMV 0.0000 with the walk-away recommended; the engine takes its maximum over the branches listed, and a branch not listed does not exist to it."]'::jsonb, 3, '0.0000 beats -52.0000, so the root would take the walk-away. The engine never adds one and never flags a negative optimal EMV.'),
  ('decision', 'beginner', 'module', 'm03-decision-nodes', 11, 'The published singleBranchDecision case has one branch, only, worth 7.0000. What does the rollback give, and what does it show?', '["EMV 7.0000 with best branch index 0 and N/A on the Builder''s next best and advantage cards, which is no evidence the branch is worth taking.", "A refusal, since a decision node needs at least two branches before it has anything to compare, and the message names the node that has too few.", "EMV 7.0000 with an advantage of 7.0000 over the walk-away at 0.0000 that the Builder adds to a single branch.", "EMV 7.0000 with a decision advantage of 0.0000, since the single branch is counted a second time as its own next best alternative on the card."]'::jsonb, 0, 'Only a node with no branches is refused. A decision with one branch is rolled back anyway to 7.0000, and the recommendation is simply the only branch drawn.'),
  ('decision', 'beginner', 'module', 'm03-decision-nodes', 12, 'With EKPAN tree success cut to 0.100000 and the dry hole at 0.750000, the root reads Drill -6.2500, Farm out 14.0000 and Walk away 0.0000. What does it recommend once the walk-away branch is removed?', '["Drill at -6.2500, since removing a branch reorders the list and the first branch listed then takes the root.", "EMV 0.0000 anyway, since with no walk-away drawn the engine floors a negative drill at zero on its own.", "Farm out at 14.0000, the same as before, because walking away was never the best branch.", "A refusal, since the drill is negative and the tree no longer carries a branch at zero to fall back on."]'::jsonb, 2, 'A walk-away that is not chosen changes nothing in the rollback. At 0.050000 the answer is the same, Farm out at 9.2500 with or without it.'),
  ('decision', 'beginner', 'module', 'm03-decision-nodes', 13, 'Why can walking away never be the strictly best branch on the EKPAN tree, whatever the success probability?', '["The drill is positive at every success probability on the EKPAN tree, so a branch worth 0.0000 can never lead the root.", "The farm-out has no cost and pays 95.0000, 30.0000 or 0.0000, none negative, so its value is never below 0.0000 and is above it whenever success or a marginal find has any chance.", "Walking away ties the farm-out at 0.0000 and loses every tie, since it is listed last among the root''s three branches.", "The engine never selects a branch paying exactly 0.0000, which it reads as a payoff missing from the tree."]'::jsonb, 1, 'The drill is not always positive: at success 0.100000 it is -6.2500. The farm-out dominates the walk-away, so the walk-away is a record of the option and not a live contender.'),
  ('decision', 'beginner', 'module', 'm03-decision-nodes', 14, 'Money already spent on a licence is drawn on a tree as a negative payoff on the walk-away branch. What does that do to the decision?', '["It is right, since the walk-away is the only branch on which the licence money is lost with nothing coming back for it, so the whole loss belongs on that branch.", "It changes nothing, since the rollback recognises a sunk cost typed as a payoff and removes it before any maximum is taken at the root decision node.", "It is refused, since a walk-away branch must pay exactly 0.0000 for the engine to accept the decision node.", "It biases the choice against walking away, since money spent before the decision is spent on every branch alike and belongs to none of them alone."]'::jsonb, 3, 'A walk-away is worth 0.0000 relative to the money still to be decided. Charging sunk money to it alone makes every other branch look better by that amount, and the engine accepts the tree without comment.'),
  ('decision', 'beginner', 'module', 'm03-decision-nodes', 15, 'A decision node deep in the EKPAN tree, the marginal find, is solved how, compared with the root?', '["Exactly like the root: it takes its largest branch value, 170.0000 from Develop, and that value feeds the drill chance node at 0.150000.", "After the root, since a decision node below a chance node is valued only once the root has chosen Drill.", "At the average of Develop''s 170.0000 and Sell''s 140.0000, since the owner cannot know which choice will follow.", "At Develop''s payoff of 260.0000, since a later decision passes its best payoff up the tree and the develop cost of 90.0000 is charged at the root instead."]'::jsonb, 0, 'The rollback runs from the leaves up, so the marginal find is solved before the drill node weights it. Its answer, 170.0000, enters 0.350000 x 420.0000 + 0.150000 x 170.0000 + 0.500000 x -25.0000 = 160.0000.'),
  ('decision', 'beginner', 'module', 'm04-rolling-back-a-sequence', 1, 'OKRIKA''s appraisal chance node weights a good result at 0.400000 and a poor result at 0.600000. Which two values does it weight?', '["375.0000 and 56.0000, the development chance nodes behind each result, since those are the next chance nodes to the right of it.", "520.0000 and -60.0000, the large and small field payoffs, because a chance node always weights the terminals that sit beneath it.", "225.0000 and 25.0000, the values of the two decisions that follow, each already reduced to its best branch after cost.", "225.0000 and -94.0000, the development branch after each result, the action the appraisal exists to test."]'::jsonb, 2, 'OKRIKA''s appraisal node weights what its children are worth after their own choices: 0.400000 x 225.0000 + 0.600000 x 25.0000 = 105.0000, and the appraisal cost of 18.0000 makes the branch 87.0000.'),
  ('decision', 'beginner', 'module', 'm04-rolling-back-a-sequence', 2, 'Read left to right, OKRIKA is a 520.0000 prize and Develop now looks like the shortest road to it. What does the rollback make of Develop now?', '["The worst of the three root branches: 183.6000 less its cost of 150.0000 is 33.6000, against Sell now at 48.0000 and Appraise at 87.0000.", "The best root branch at 183.6000, since it reaches the large field without first paying the appraisal cost of 18.0000.", "Second best, behind Appraise and ahead of Sell now at 48.0000, because developing today avoids the delay an appraisal adds.", "Level with Appraise at 87.0000, because the chance of a large field is 0.420000 by either route and both weight the same two outcomes."]'::jsonb, 0, 'Develop now weights 0.420000 x 520.0000 + 0.580000 x -60.0000 = 183.6000, the node value before the cost; the branch is 33.6000, and the root takes Appraise at 87.0000.'),
  ('decision', 'beginner', 'module', 'm04-rolling-back-a-sequence', 3, 'What is OKRIKA''s decision after a poor appraisal worth, and which branch does it take?', '["56.0000, the development, reading the development chance node before its cost of 150.0000 as if it were the branch value.", "-94.0000, the development, because development is the only branch after an appraisal that can still reach the large field at 520.0000.", "95.0000, the sale, using the sale price after a good appraisal, which the tree applies to any sale made once the appraisal is done.", "25.0000, the sale, because developing is worth 56.0000 less 150.0000 = -94.0000 there."]'::jsonb, 3, 'After a poor result the chance of a large field is 0.200000: 0.200000 x 520.0000 + 0.800000 x -60.0000 = 56.0000, less 150.0000 is -94.0000, which loses to the sale typed at 25.0000.'),
  ('decision', 'beginner', 'module', 'm04-rolling-back-a-sequence', 4, 'Delete both sales inside OKRIKA''s appraisal branch, so the company must develop whatever the appraisal says. What does the root do?', '["It still appraises at 87.0000, since the sale after a good appraisal was never taken and the one after a poor result was a fallback.", "It sells now at 48.0000, because the appraisal branch falls to 0.400000 x 225.0000 + 0.600000 x -94.0000 = 33.6000, less 18.0000 = 15.6000.", "It appraises at 33.6000, since without the sales the appraisal node equals Develop now and the appraisal is listed first.", "It appraises at 71.4000, the value the appraisal branch keeps once the option to sell is taken out, still ahead of Sell now."]'::jsonb, 1, 'Without the sales a poor result forces the development at -94.0000, the appraisal branch drops to 15.6000 and loses to Sell now at 48.0000, so the root sells today.'),
  ('decision', 'beginner', 'module', 'm04-rolling-back-a-sequence', 5, 'When OKRIKA''s sales are deleted the appraisal branch moves from 87.0000 to 15.6000, a difference of 71.4000. What is 71.4000?', '["The value of the appraisal itself, since it is exactly what the appraisal branch loses when the tree is drawn without it.", "The value of the option to sell after a poor result, inside a branch that also pays the appraisal cost.", "The value of reducing uncertainty about the field size, which the appraisal buys for the company whether or not a sale follows it.", "The advantage of appraising over selling now, the margin the root holds over its best alternative."]'::jsonb, 1, 'The whole difference sits on the poor side, carried at 0.600000, because the sale after a good result was never taken; the appraisal''s advantage over Sell now is a different number, 39.0000.'),
  ('decision', 'beginner', 'module', 'm04-rolling-back-a-sequence', 6, 'On OKRIKA, Sell after a good appraisal reads onOptimalPath false and Sell after a poor appraisal reads true. What does that tell a reader who wants to prune the tree?', '["Both can go, because each sale pays less than the large field''s 520.0000 and a rollback only needs the branches that can win big.", "Neither can go, since every branch enters its parent''s weighting, on the optimal path or off it.", "The one reading false carries the value, since the flag marks branches held in reserve.", "The first can go without changing a number; the second carries 71.4000 of the appraisal branch''s value."]'::jsonb, 3, 'A decision node hands up only its best branch, so a branch never taken changes nothing when removed; the sale after a poor result is the branch taken, and removing it drops the appraisal branch from 87.0000 to 15.6000.'),
  ('decision', 'beginner', 'module', 'm04-rolling-back-a-sequence', 7, 'With both sales deleted, OKRIKA''s appraisal chance node comes to 33.6000, exactly the value of Develop now. Why do the two agree?', '["An appraisal that cannot change what the company does is the same development delayed, and the tree''s chances agree: 0.400000 x 0.750000 + 0.600000 x 0.200000 = 0.420000.", "The engine copies the root''s Develop now value into any chance node whose later decisions have lost all their alternatives.", "They agree by coincidence of the typed payoffs, and a tree with a different sale price after a poor result would pull them apart.", "An appraisal with no sale behind it reduces no uncertainty, so the engine values its node at the chance of a large field known beforehand."]'::jsonb, 0, 'Both lines weight 520.0000 and -60.0000 at a combined 0.420000 and pay 150.0000, so the appraisal only adds its 18.0000 bill; it earns value because a poor result leads to the sale, and uncertainty is reduced the same in both trees.'),
  ('decision', 'beginner', 'module', 'm04-rolling-back-a-sequence', 8, 'OKRIKA''s later chances happen to agree with its earlier ones, 0.400000 x 0.750000 + 0.600000 x 0.200000 = 0.420000. What does the engine do with a tree whose later chances disagree?', '["It refuses the tree, with the same message it gives a chance node whose probabilities do not sum to 1 within 1e-6.", "It rescales the later probabilities until they reproduce the earlier chance, and then rolls the corrected tree back.", "It rolls the tree back just the same, with no warning, because it has no link between chance nodes beyond the tree as drawn.", "It rolls the tree back but marks every branch below the disagreeing chance nodes onOptimalPath false, so the reader can find them."]'::jsonb, 2, 'The 1e-6 test looks at each chance node on its own; a tree whose appraisal results imply a different chance of a large field than the 0.420000 Develop now uses is accepted silently.'),
  ('decision', 'beginner', 'module', 'm04-rolling-back-a-sequence', 9, 'A published refusal places a chance node summing to 0.200000 two levels below an otherwise valid root. What comes back?', '["A rollback of the valid parts, with the bad subtree valued at 0 and the message attached to the node named cc as a note.", "A rollback with the bad node''s probabilities scaled up to sum to 1, as a likely entry error.", "A refusal only if the bad node lies under the root''s best branch, since a branch the root would never take cannot move the answer.", "A refusal of the whole tree: \"Chance branch probabilities sum to 0.200000, expected 1 (at node \"cc\")\"."]'::jsonb, 3, 'Depth hides nothing from the checks and there is no partial rollback: a bad distribution anywhere refuses the tree, and on a valid tree like deepAlternation the root is 6.0000 only because every node below it passed.'),
  ('decision', 'beginner', 'module', 'm04-rolling-back-a-sequence', 10, 'The published chanceRootWithBranchCosts tree has calm at 0.600000 with cost 2.0000 over a child of 19.0000, and storm at 0.400000 with cost 8.0000 over -25.0000. The engine returns -3.0000. What produces -8.6000?', '["Weighting the children first and subtracting both costs once afterwards, which charges each cost on the branch where it is not paid.", "Charging each cost on its own branch before the root weights it, the engine''s rule applied to a root that is a chance node.", "Weighting each cost by its own branch probability and subtracting the result, the engine''s order simply written the other way round.", "Charging the storm cost of 8.0000 on its branch and again at the root, because a cost on a losing branch is counted against the whole tree."]'::jsonb, 0, 'The engine pays 2.0000 only on calm and 8.0000 only on storm, giving branch values 17.0000 and -33.0000 and a root of -3.0000; taking both costs off the weighted sum charges each on every path.'),
  ('decision', 'beginner', 'module', 'm04-rolling-back-a-sequence', 11, 'In deepAlternation, push costs 6.0000 and sits under the up branch, which happens with probability 0.500000, while go costs 4.0000 at the root. Where is each cost paid?', '["Both at the root, since a rollback gathers every cost in the tree and settles them once all the chance nodes have been weighted.", "Push on both up and down, since a cost below a chance node is spread across its outcomes.", "Push only on the up branch, before L1 weights it, and go on every path through the root''s best branch.", "Push only when win arrives, since a cost on the way into a chance node is charged against the outcome that justifies paying it."]'::jsonb, 2, 'A cost is charged only when its branch is taken: L2 is 29.0000 less 6.0000 = 23.0000 against hold at 12.0000, L1 is 0.500000 x 23.0000 + 0.500000 x -3.0000 = 10.0000, and go makes the root 6.0000.'),
  ('decision', 'beginner', 'module', 'm04-rolling-back-a-sequence', 12, 'Which branches of deepAlternation read onOptimalPath false?', '["Hold, stop, lose and down, every branch that leads somewhere worse than the best payoff available at its own node.", "Hold and stop, the two decision branches the rollback did not take.", "Stop, down and lose, the branches that end at a terminal paying less than the root''s value of 6.0000.", "Only stop, since hold sits beneath the root''s best branch and everything under a taken branch stays on the path."]'::jsonb, 1, 'A chance node does not choose, so up, down, win and lose all stay on the path under a taken branch; inside each decision only the best branch reads true, which leaves hold at 12.0000 and stop at 1.0000 off it.'),
  ('decision', 'beginner', 'module', 'm04-rolling-back-a-sequence', 13, 'deepAlternation rolls back to 6.0000 along a path that runs go, then up and down, then push, then win and lose. What is 6.0000?', '["An average over paths that pay quite different amounts, none of which needs to be 6.0000.", "The payoff of the most likely route through the tree, since the path follows the branches the rollback kept.", "What the company receives if it follows the optimal path at every decision, whichever outcomes arrive along the way.", "The worst the company can reach along the optimal path, once the costs of go and push have both been paid."]'::jsonb, 0, 'Win after push pays 50.0000 before the costs of 6.0000 and 4.0000, and down pays -3.0000 before the 4.0000; the root weights these, so 6.0000 is a mean and the path is a plan, never a forecast.'),
  ('decision', 'beginner', 'module', 'm04-rolling-back-a-sequence', 14, 'The Decision Tree Builder''s drawing labels OKRIKA''s development chance node after a good appraisal with its own value, 375.0000. What happens if that figure is weighted into the appraisal node?', '["Nothing changes, because the drawing''s label and the branch value are the same number whenever the branch lies on the optimal path.", "The good branch is overstated by OKRIKA''s sale price of 95.0000, which the drawing adds to the development as its fallback.", "The appraisal branch comes out slightly low, because the label is rounded for display while the rollback weights the unrounded value.", "The good branch is overstated by the whole 150.0000 development cost."]'::jsonb, 3, 'A node label is the value before the cost on the branch into it; the appraisal node takes 225.0000 after a good result and 25.0000 after a poor one, never 375.0000 or 56.0000.'),
  ('decision', 'beginner', 'module', 'm04-rolling-back-a-sequence', 15, 'OKRIKA''s appraisal cost of 18.0000 and development cost of 150.0000 are paid at different times, and its sale after a poor result is typed at 25.0000. What does the rollback check about either?', '["It discounts the development cost by its depth, since each later layer stands for a later date.", "It checks the sale after a poor result against the sale now at 48.0000 and refuses a later sale priced below today''s.", "Neither: it has no clock, so every number must arrive discounted to one date, and it takes each sale price as typed.", "It discounts nothing but adds a risk premium at each layer, as a sequence carries more uncertainty."]'::jsonb, 2, 'The engine is risk neutral with no discounting at every layer, and it does not ask whether a buyer would pay 25.0000 for a discovery just appraised as poor, although 25.0000 is below the 48.0000 on offer today.'),
  ('decision', 'beginner', 'module', 'm05-when-the-decision-changes', 1, 'Where do the EKPAN lottery''s Drill and Farm out branches cross?', '["At 0.250000 on the lottery, the first sweep row where Drill beats Farm out.", "At 80 / 350 = 0.228571 on the lottery, solved from Drill = 445 p - 80 and Farm out = 95 p.", "At 80 / 445 = 0.179775 on the lottery, the probability where the drill branch''s value falls to zero.", "At 0.200000 on the lottery, the last sweep row where Farm out is best."]'::jsonb, 1, 'The EKPAN lottery''s sweep rows sit 0.050000 apart, so they bracket the switch between 0.200000 and 0.250000 and cannot place it; 0.179775 is Drill against Walk away, where Farm out already wins at 95 p.'),
  ('decision', 'beginner', 'module', 'm05-when-the-decision-changes', 2, 'At success 0.228571 on the EKPAN lottery the engine prints Drill 21.7143 and Farm out 21.7143 and names Farm out, although Drill is listed first. Why Farm out?', '["Ties go to the branch that cannot lose money, and the lottery''s farm-out never loses.", "The tie rule keeps the branch listed first, and the engine re-lists the lottery''s actions by value, which puts Farm out first below the switch.", "The engine treats a probability typed to six decimals as rounded, and on the lottery it falls back to the farm-out when two values look level.", "Drill less Farm out comes out at -7.11e-15 on the lottery, because 80 / 350 has no exact binary image."]'::jsonb, 3, 'A true tie would go to Drill, the first branch listed; the EKPAN lottery''s choice at 0.228571 is rounding residue under a strictly greater test, so report the switch and no winner at it.'),
  ('decision', 'beginner', 'module', 'm05-when-the-decision-changes', 3, 'Swept, the published drillFarmOut tree reads Drill 12.0000 and Farm out 12.0000 at success 0.200000 and names Drill. How should that row be reported?', '["The two are indifferent at 0.200000; Drill is named only because it is listed first, and the advantage is 0.0000.", "Drilling is better from 0.200000 upward, since the engine names Drill at the first row where it is no longer behind.", "Farm out is best up to and including 0.200000, since a tie on a published tree is resolved toward the branch that cannot lose.", "Drill wins by a residue too small to print, the same way the EKPAN lottery''s crossing at 0.228571 is decided."]'::jsonb, 0, 'The drillFarmOut tie is exact to the last digit, so the tie rule decides it; the EKPAN lottery''s crossing is decided by -7.11e-15 of residue instead, and neither result is a recommendation.'),
  ('decision', 'beginner', 'module', 'm05-when-the-decision-changes', 4, 'The published drillFarmOut sweep moves its success probability in the drill''s chance node and the farm-out''s chance node together. Why both at once?', '["Because the engine refuses a tree whose two chance nodes carry different success probabilities, with the same message it gives a sum that is off.", "Because moving the drill''s node alone would leave the farm-out''s node summing to something other than 1 within 1e-6, so that tree would be refused.", "So each row judges Drill and Farm out on the same prospect; the engine links no chance node to another and would roll back a row that moved only one.", "Because the farm-out''s payoffs are scaled to the success probability, and a sweep has to rescale them at every row before the two branches are compared."]'::jsonb, 2, 'Each row is a separate rollback with the payoffs held as typed, so at 0.200000 both branches are 12.0000 on one prospect. The engine checks each chance node''s own sum and has no link between chance nodes, so a mismatched row would roll back without a warning.'),
  ('decision', 'beginner', 'module', 'm05-when-the-decision-changes', 5, 'What does the engine report to tell a reader that its recommended branch is tied with the runner-up?', '["A tie flag on the decision node, set when two branch values agree to four decimals.", "The runner-up''s index beside the best, so a tie shows as two branches on the optimal path.", "Nothing: it returns one best branch index whether the runner-up is behind by 25.0000 or by nothing.", "A warning in place of a recommendation whenever two branch values agree within the same 1e-6 tolerance its chance nodes use."]'::jsonb, 2, 'The rollback cannot tell an exact tie, like drillFarmOut''s 12.0000 at 0.200000, from a residue of -7.11e-15 like the EKPAN lottery''s at 0.228571; both come back as one best branch.'),
  ('decision', 'beginner', 'module', 'm05-when-the-decision-changes', 6, 'On the EKPAN lottery, moving success from 0.350000 to 0.400000 lifts the EMV from 75.7500 to 98.0000, and moving it from 0.200000 to 0.250000 lifts it from 19.0000 to 31.2500. Which move matters to a decision maker?', '["The smaller move lower down on the lottery, which changes the first move from Farm out to Drill.", "The larger move on the lottery, because the EMV rises by more and a decision is only as sensitive as the value it rests on.", "Neither, because the lottery''s EMV rises steadily across the whole sweep, so the success probability never decides the first move.", "Both equally, because each row of the lottery''s sweep is a separate rollback and every rollback returns a fresh recommendation."]'::jsonb, 0, 'The biggest changes in value sit well inside the EKPAN lottery''s Drill region, where the action never changes; the choice turns between 0.200000 and 0.250000, which is what a decision maker needs.'),
  ('decision', 'beginner', 'module', 'm05-when-the-decision-changes', 7, 'A reader raises the EKPAN lottery''s success probability from 0.350000 to 0.400000 and leaves its dry hole at 0.650000. What does the engine do?', '["Rescales both probabilities so they sum to 1, and rolls the lottery back at a success chance slightly below 0.400000.", "Rolls back at 0.400000 as typed and returns the lottery''s Drill value of 98.0000, since only success enters the drill line.", "Takes the dry hole as 1 less the success chance, since a two-outcome lottery only needs the one probability to roll back.", "Refuses the chance node, because its probabilities no longer sum to 1 within 1e-6."]'::jsonb, 3, 'A probability cannot move alone: the EKPAN lottery''s 98.0000 at 0.400000 is a rollback with the dry hole moved down to 0.600000 by the same amount, and a node that does not sum to 1 is refused.'),
  ('decision', 'beginner', 'module', 'm05-when-the-decision-changes', 8, 'The EKPAN tree at success 0.100000 reads Drill -6.2500, and the EKPAN lottery at 0.100000 reads Drill -35.5000. Why do the two disagree?', '["The tree''s drill is read before its cost of 55.0000 and the lottery''s after it, so they differ by that cost.", "The tree keeps its marginal find at 0.150000 and develops it, while the lottery folds that probability into its dry hole.", "The lottery''s value comes off a sweep grid and the tree''s from an exact rollback, so one is rounded.", "The tree''s dry hole stays at 0.500000 as success moves, so its sum drifts from 1 and is let through."]'::jsonb, 1, 'The EKPAN tree at 0.100000 carries a dry hole of 0.750000 and a marginal find worth 170.0000; the EKPAN lottery has two outcomes only, so a value from either model is not a point on the other''s curve.'),
  ('decision', 'beginner', 'module', 'm05-when-the-decision-changes', 9, 'Why is walking away never the best action on the EKPAN lottery at a success probability above 0?', '["The lottery''s farm-out pays 0.0000 on a dry hole, as walking away does, and 95.0000 on success, so at 95 p it beats walking away wherever success is possible.", "On the lottery Drill crosses Walk away at 0.179775 and Farm out at 0.228571, and the engine only acts on the higher of two crossings.", "Walking away is dropped from the lottery below 0.179775, where Drill is negative, so it is never compared with anything there.", "The tie rule keeps Farm out whenever it and Walk away are level, and on the lottery the two are level at every success probability."]'::jsonb, 0, 'An action that equals another in one outcome and beats it in the other can never be worth less; the EKPAN lottery''s Drill against Walk away crossing at 0.179775 lies where Farm out already wins.'),
  ('decision', 'beginner', 'module', 'm05-when-the-decision-changes', 10, 'At success 0.100000 on the EKPAN lottery a reader sees Drill at -35.5000 and concludes: walk away. What does that answer give up?', '["Nothing, because a negative drill on the lottery means no action on that prospect is worth more than walking away.", "The lottery''s drill at 9.0000, since the drill turns positive at that probability once the farm-out is taken off the table.", "The lottery''s farm-out at 19.0000, since a farm-out is valued at the switch probability rather than at the probability stated.", "The lottery''s farm-out at 9.5000, the best of its three actions there."]'::jsonb, 3, 'A negative drill says only that drilling is worse than nothing; the best action needs every branch compared at once, and at 0.100000 the EKPAN lottery''s Farm out is 9.5000 against Walk away at 0.0000.'),
  ('decision', 'beginner', 'module', 'm05-when-the-decision-changes', 11, 'The farm-out terms are not agreed, so a tree for the EKPAN lottery is drawn with only Drill and Walk away. Where does its first move switch?', '["At 0.228571, since on the lottery the switch belongs to the prospect and not to whichever branches happen to be drawn.", "At 0.179775, below the lottery''s true switch of 0.228571, so across the whole farm-out region the tree chooses wrongly.", "At 0.250000, the first row of the lottery''s sweep where Drill beats everything the tree has left to compare it with.", "Nowhere, since without the farm-out the lottery''s tree drills at every probability and the walk-away branch is never taken."]'::jsonb, 1, 'The engine compares only the branches drawn: the EKPAN lottery''s Drill = 445 p - 80 crosses Walk away at 80 / 445, so the tree walks away and then drills where Farm out would have won.'),
  ('decision', 'beginner', 'module', 'm05-when-the-decision-changes', 12, 'The EKPAN lottery''s drill is worth 75.7500 and leaves 365.0000 with probability 0.350000 or -80.0000 with probability 0.650000. What does the rollback return about that loss?', '["The lottery''s chance of loss, 0.650000, beside the EMV, since every chance node reports the weight on its negative outcomes.", "A worst case of -80.0000 on the lottery''s drill, since the optimal path lists the terminal payoffs that it passes through.", "Nothing: an EMV, the best branch and the optimal path, with no chance of loss, worst case or range.", "A warning that the lottery''s drill usually loses, its loss chance being above 0.500000."]'::jsonb, 2, 'The EKPAN lottery''s outcome table is derived by hand from the payoffs and the 55.0000 cost; neither 365.0000 nor -80.0000 is near 75.7500, and the engine reports neither.'),
  ('decision', 'beginner', 'module', 'm05-when-the-decision-changes', 13, 'A company cannot absorb a loss of 80.0000 on one well. On the EKPAN lottery at 0.350000, what does the engine recommend, and why?', '["Farm out at 33.2500 on the lottery, because the engine prefers an action that never loses when the other loses with probability 0.650000.", "Drill on the lottery, but only once the module''s risk aversion parameter is set to neutral.", "Farm out on the lottery, since a loss chance above 0.500000 makes the drill too risky to recommend.", "Drill at 75.7500 over the lottery''s Farm out at 33.2500, because it maximises expected money with no utility function."]'::jsonb, 3, 'The rollback is risk neutral and no risk aversion setting exists in either module: a company may rationally take the EKPAN lottery''s farm-out, and the tree still recommends the drill by its larger mean.'),
  ('decision', 'beginner', 'module', 'm05-when-the-decision-changes', 14, 'The EKPAN lottery''s sweep pays Farm out 95.0000 on success at 0.050000 and at 0.250000 alike. What does that say about the sweep?', '["The engine holds each payoff at its typed value while the lottery''s probability moves, though no partner would offer those terms on a much weaker prospect.", "The lottery''s farm-out terms are fixed by contract, which is why the engine refuses a farm-out payoff that changes with the probability.", "The engine rescales the lottery''s farm-out payoff at each row and prints only the stated value, so the column is the terms at 0.350000.", "The lottery''s sweep is invalid below the switch, since a payoff held fixed across rows only means something where its action is chosen."]'::jsonb, 0, 'A sweep is a list of separate rollbacks with the payoffs as typed; the EKPAN lottery''s lines are straight only because 95.0000 and 420.0000 stay put as p moves.'),
  ('decision', 'beginner', 'module', 'm05-when-the-decision-changes', 15, 'On the EKPAN tree the success payoff is linked to a Monte Carlo NPV summary with mean 420, P90 185 (the low case) and P10 710. What does the tree read?', '["37.7500 on the tree, since a linked payoff enters at its P90, the low case.", "105.0000, the same as a flat 420.0000 on the tree, because only the mean enters the rollback.", "206.5000 on the tree, since a linked payoff enters at its P10, the high case, the value a prospect is promoted on.", "A value on the tree weighted across the summary''s mean, P90 and P10, since the link stores all three for the rollback to use."]'::jsonb, 1, 'The rollback is linear, so the mean is the only statistic it needs and the spread stays hidden; read at the P90 of 185 the EKPAN tree would fall to 37.7500 and flip to the farm-out.'),
  ('decision', 'beginner', 'module', 'm06-the-associate-reading', 1, 'The Decision Tree Builder''s drawing labels the EKPAN tree''s drill chance node EMV 160. A graded question asks for the drill branch''s value. What goes wrong if the label is copied?', '["Nothing, since the EKPAN tree''s drill is on the optimal path, where a label equals the branch value.", "Only the precision: the drawing prints 160, and the EKPAN tree''s drill branch is 160.0000.", "The answer adds the marginal find''s sale at 140.0000 into the EKPAN tree''s node as a fallback.", "The answer is 160.0000 where the EKPAN tree''s drill branch is 105.0000, wrong by exactly the drill cost of 55.0000."]'::jsonb, 3, 'A node label is the value before the cost on the branch into it: on the EKPAN tree 0.350000 x 420.0000 + 0.150000 x 170.0000 + 0.500000 x -25.0000 = 160.0000, less 55.0000 = 105.0000.'),
  ('decision', 'beginner', 'module', 'm06-the-associate-reading', 2, 'What do the next best alternative and the decision advantage read for OKRIKA?', '["Develop now at 33.6000, the branch listed second, which the card takes as the runner-up whatever its value.", "Sell now at 48.0000, and an advantage of 39.0000 for Appraise.", "Sell now at 48.0000, and an advantage of 71.4000, the value the later sale adds inside the appraisal branch.", "Develop now at 183.6000, since the card reads each alternative at its node before the development cost of 150.0000."]'::jsonb, 1, 'The next best card takes the largest other root branch value, 48.0000, and the advantage is 87.0000 less 48.0000 = 39.0000; 71.4000 compares the appraisal with and without its later sale.'),
  ('decision', 'beginner', 'module', 'm06-the-associate-reading', 3, 'On OKRIKA, the development chance node after a poor appraisal sits under a Develop branch reading onOptimalPath false. Its Large and Small probabilities are retyped so they sum to 0.9. What comes back for OKRIKA?', '["A refusal of the whole tree naming that node and printing 0.900000, with no EMV for Appraise, Develop now or Sell now.", "The root at 87.0000 unchanged, since that development reads onOptimalPath false and the sale at 25.0000 is what the appraisal node weights.", "Sell now at 48.0000, the only root branch that passes through no chance node, with the other two root branches reported as refused.", "The root with that node''s probabilities rescaled to sum to 1, since a node below a branch the rollback does not take is repaired quietly rather than refused."]'::jsonb, 0, 'The sum is checked at every chance node however deep, taken or not: the rollback still values that development at -94.0000 before the decision sets it against the sale at 25.0000. A refusal returns no EMV for any part of the tree, and the engine never rescales.'),
  ('decision', 'beginner', 'module', 'm06-the-associate-reading', 4, 'A reader types the EKPAN tree''s success payoff as 185, the P90 (the low case) of its Monte Carlo NPV summary, instead of linking the summary whose mean is 420. What does the tree read?', '["105.0000 with Drill, since the P90 is the cautious figure and a drill on the tree that survives it survives the mean as well.", "94.5000 with Drill, since 185 sits near the P50 and the tree moves only part way.", "37.7500 with Farm out first, where the linked summary would have given the tree 105.0000 with Drill.", "22.7500 with Drill, the tree''s drill branch at that payoff, since Drill is the only branch that can reach the success payoff."]'::jsonb, 2, 'At 185.0000 the EKPAN tree''s drill branch is 22.7500, below Farm out at 37.7500, so the choice flips; linked, only the mean enters and the tree reads 105.0000.'),
  ('decision', 'beginner', 'module', 'm06-the-associate-reading', 5, 'Rolled back without its walk-away branch, what does the EKPAN tree read at its stated probabilities and at success 0.050000?', '["105.0000 with Drill, and Farm out at 9.2500 at 0.050000, exactly as with the walk-away branch drawn on the tree.", "105.0000 with Drill, but at 0.050000 the tree takes Drill at -28.5000, since with no walk away the least bad branch is the drill.", "Less than 105.0000 on the tree, since removing a branch lowers a decision by the weight it carried.", "0.0000 at 0.050000, since walking away is the tree''s floor and the root has nothing left under it."]'::jsonb, 0, 'A decision takes its best branch, so removing one that is never best leaves every root value unchanged; at 0.050000 the EKPAN tree''s Farm out 9.2500 beats Drill at -28.5000 either way.'),
  ('decision', 'beginner', 'module', 'm06-the-associate-reading', 6, 'Which of these first moves is the tie rule speaking, and nothing else?', '["Farm out on the EKPAN lottery at 0.228571, where both branches print 21.7143 and the lottery keeps the branch the engine met first.", "Develop in the EKPAN tree''s marginal find, where 260.0000 less its cost of 90.0000 beats selling at 140.0000 within the rule''s margin.", "Appraise on OKRIKA at 87.0000, because the appraisal is listed first of the three root branches and the rule favours that position.", "Drill on the published drillFarmOut tree at success 0.200000, where both branches are 12.0000."]'::jsonb, 3, 'An exact tie at drillFarmOut''s 0.200000 goes to Drill because it is listed first, with an advantage of 0.0000; the EKPAN lottery''s Farm out at 0.228571 is residue of -7.11e-15, and Develop at 170.0000 and Appraise by 39.0000 are real margins.'),
  ('decision', 'beginner', 'module', 'm06-the-associate-reading', 7, 'The EKPAN tree''s drill branch is worth 105.0000. Which statement about what a drilled well delivers is right?', '["On the tree it delivers 105.0000 in the typical case, since an EMV is the outcome a well is most likely to produce.", "On the tree it leaves 365.0000, 115.0000 or -80.0000 after its cost, loses money with probability 0.500000, and never delivers 105.0000.", "On the tree it loses money with probability 0.650000, the dry hole chance once the marginal find is counted as a failure.", "On the tree it loses money only on the dry hole''s -25.0000, since the drill cost of 55.0000 is already inside the EMV."]'::jsonb, 1, 'Each outcome less the 55.0000 drill cost gives the EKPAN tree''s three amounts; 0.650000 is the EKPAN lottery''s loss chance, a different model that folds the marginal find into its dry hole, and mixing the two is the mistake.'),
  ('decision', 'beginner', 'module', 'm06-the-associate-reading', 8, 'The Onward reading calls OKRIKA''s appraisal the idea of information in miniature. Which numbers carry that idea?', '["OKRIKA''s appraisal branch is 105.0000 before its cost and 87.0000 after, so it is worth its price of 18.0000.", "A poor result cuts the chance of a large field from 0.420000 to 0.200000, and the uncertainty removed is what the appraisal is worth.", "The appraisal branch is 15.6000 when its result cannot change the action and 87.0000 when a poor result leads to a sale.", "The appraisal leads Sell now by 39.0000, the most the company should pay for any appraisal."]'::jsonb, 2, 'Information is worth what it can change: with no sale the appraisal leaves the development unchanged and loses to Sell now at 48.0000, and with the sale the option inside the branch is worth 71.4000.'),
  ('decision', 'beginner', 'module', 'm06-the-associate-reading', 9, 'On the EKPAN lottery EVPI is 61.7143 at a success probability of 0.228571 and 52.0000 at the stated 0.350000. Why is it largest at 0.228571?', '["It is where the lottery''s drill loses money least often, so knowing the outcome recovers most.", "It is the lottery''s drill against farm-out switch, where the choice made without information is least settled.", "EVPI on the lottery rises as success grows less likely, climbing all the way down to 0.050000.", "It is where the lottery''s Farm out is named by residue, and EVPI is measured against that error."]'::jsonb, 1, 'Perfect information is worth most where the prior decision is closest to turning; at the EKPAN lottery''s stated 0.350000 the drill already leads 75.7500 to 33.2500, and at 0.050000 EVPI is only 13.5000.'),
  ('decision', 'beginner', 'module', 'm06-the-associate-reading', 10, 'The EKPAN lottery''s information tree ties its two root branches at a survey cost of 24.8250. What does the engine recommend there?', '["No further information, because at a net value of 0.0000 on the lottery the engine declines to spend money that buys nothing.", "A refusal, since a lottery survey priced at its gross value leaves no best branch.", "No further information, because 24.8250 is judged against the lottery''s EVPI of 52.0000 and falls short of perfect information.", "Acquire CSEM survey, the first branch listed on the lottery''s information tree, by the tie rule."]'::jsonb, 3, 'At a survey cost of 24.8250 both root branches of the EKPAN lottery''s information tree are 75.7500 and the acquisition is listed first; the advantage is 0.0000, so the recommendation is only the tie rule.'),
  ('decision', 'beginner', 'module', 'm06-the-associate-reading', 11, 'The EKPAN lottery''s survey typed into the VOI Analyzer gives a gross value of information of 19.84 in its guidance sentence, while the same survey is worth 24.8250 on the lottery. What separates them?', '["The Analyzer offers two actions only, the named decision and Do Not, so the lottery''s farm-out is missing from 19.84.", "The Analyzer rounds the lottery''s posteriors to two decimals before valuing them, which costs the gross value a few million USD.", "The 19.84 is net of the lottery''s survey cost of 8.0000, while 24.8250 is the gross value before that cost is paid.", "The Analyzer withholds part of the lottery''s value, because the typed indicator chances contradict the stated 0.350000."]'::jsonb, 0, 'With Farm out removed the EKPAN lottery''s survey is worth 19.8375, the two-action number the Analyzer prints as 19.84; the posteriors were typed at full precision and the inputs read consistent true.'),
  ('decision', 'beginner', 'module', 'm06-the-associate-reading', 12, 'On IRRI both indicators are typed 20 / 80 percent. What does the repaired VOI Analyzer report for the value of information?', '["A gross value of -15.00, the figure printed on those inputs before the repair, which it now shows beside a warning.", "A value of 0.00, since two readings with the same outcome chances cannot change the decision.", "It withholds it, with consistent false, and still reports EMV without information 15.00 and EVPI 63.00.", "A refusal before anything is computed, since chances that disagree are not chances at all."]'::jsonb, 2, 'The typed numbers are chances that cannot all be true, implying 0.200000 success against a stated 0.300000; before the repair the Analyzer printed -15.00, which Bayes can never produce because information is never worth less than 0.'),
  ('decision', 'beginner', 'module', 'm06-the-associate-reading', 13, 'Rolling back a tree in writing, a learner''s line disagrees with the explorer at one node. What does the working method say to do?', '["Write down the explorer''s root, since hand lines are where errors enter.", "Carry on to the root, since one node''s disagreement is diluted by the weighting above it.", "Move one probability and roll back again, since a disagreement at a single node usually means the tree sits near its switch.", "Stop at the first disagreement and find it, since the root is only as right as everything beneath it."]'::jsonb, 3, 'The explorer rolls back whatever was typed, a wrong probability, cost or link included, so the method compares node by node; on OKRIKA the lines run 375.0000, 225.0000, 56.0000, 25.0000, 105.0000 and 87.0000.'),
  ('decision', 'beginner', 'module', 'm06-the-associate-reading', 14, 'What can a rolled-back tree in this tier not tell a company about the EKPAN lottery''s drill?', '["Whether the lottery''s probabilities are right, what a loss of 80.0000 means to the licence holder, or what learning the outcome before committing 55.0000 is worth.", "Its first move on the lottery, since a risk neutral rollback reports an EMV and leaves the choice between the branches to the reader.", "Its value in today''s money on the lottery, since the rollback discounts each payoff by the stage it sits at and never shows the rate.", "Whether the lottery''s probabilities sum to 1, since the engine accepts any chance node and reports its sum only as a note."]'::jsonb, 0, 'The engine returns a risk neutral EMV of 75.7500 for the EKPAN lottery''s drill with a best branch and a path, refuses a bad sum and applies no rate; what information is worth before the 55.0000 is committed is the next tier''s question.'),
  ('decision', 'beginner', 'module', 'm06-the-associate-reading', 15, 'On the published allNegative tree, branch A is worth -55.0000 and branch B -52.0000. What does the engine return?', '["A refusal, since a decision node with no branch above 0 has no choice that is worth recommending to anyone.", "B as the first move at an EMV of -52.0000, an advantage of 3.0000 over A.", "A at -55.0000, since the decision takes the largest branch value and the engine compares the sizes of the two losses.", "An EMV of 0.0000 with no first move, since walking away is implied whenever every branch drawn in the tree loses money."]'::jsonb, 1, 'A decision takes the maximum even when every branch loses: -52.0000 is greater than -55.0000, and the engine never adds a walk-away branch the tree does not draw.'),
  ('decision', 'beginner', 'final', null, 1, 'A board says it cannot survive a loss of 80.0000 million USD on one well, and the EKPAN tree still recommends the drill at 105.0000. Why does the board''s position change nothing in the rollback?', '["The loss is already priced in, because the EKPAN tree''s dry hole of -25.0000 was discounted at a risk premium before it was typed into its terminal.", "The limit bears on the farm-out as well, so it lowers both branch values together and leaves their order at the root unchanged.", "The engine is risk neutral: it maximises expected money and has no utility function or risk aversion setting where that limit could be entered.", "The EKPAN tree''s drill cost of 55.0000 is charged before weighting, which caps the loss the rollback can see at the cost rather than at the whole dry hole outcome."]'::jsonb, 2, 'On the EKPAN tree the drill loses money with probability 0.500000 and still wins, 105.0000 against 37.7500, because the rollback ranks branches by their averages alone.'),
  ('decision', 'beginner', 'final', null, 2, 'A tree arrives with one of its nodes typed "lottery" and every probability inside the range 0 to 1. What does the engine return?', '["A refusal naming an unknown node type at that node, and no EMV for any part of the tree.", "An ordinary rollback that treats the node as a chance node, since a lottery is a set of weighted outcomes and its probabilities already sum to 1.", "A rollback of the valid remainder, with the unrecognised node entered in its parent as a terminal worth 0.0000 until it is retyped.", "The EMV of every level above the node, stopping where the tree stops being well formed and reporting the deepest valid value as the root."]'::jsonb, 0, 'The engine knows decision, chance and terminal nodes only and never guesses what a malformed node meant; as the published sum of 0.200000 two levels down shows, a refusal anywhere returns nothing.'),
  ('decision', 'beginner', 'final', null, 3, 'An analyst discounts the EKPAN tree''s payoffs by hand, although another engine had already discounted them, and leaves the drill cost of 55.0000 as typed. What does the rollback report?', '["A refusal, because the engine compares each payoff against the rate stored with its linked run and detects the second discount.", "The same 105.0000 for the EKPAN tree, since the rollback restates every payoff to the date of the root decision before it weights them.", "A larger EMV, because a smaller dry hole loss lifts the drill''s weighted value by more than the shrunken success payoff takes away.", "A smaller EMV with no warning, pulled toward the branch that carries less cost, because every payoff shrank while the cost stayed at face value."]'::jsonb, 3, 'The engine has no rate, no date and no field for either, so 420.0000 and -25.0000 enter the drill chance node exactly as typed and a second discount leaves no trace.'),
  ('decision', 'beginner', 'final', null, 4, 'A tree passes every check the engine makes: known node types, at least one branch per node, and probabilities summing to 1 within 1e-6. What has that established?', '["That the recommended branch is robust, since a choice that turned inside the tolerance of 1e-6 would have been refused as ambiguous.", "Only that the tree is well formed; nothing about whether its payoffs are discounted, its probabilities true, or its branches complete.", "That no better branch was left off, since a decision node refuses to roll back when a walk-away at 0.0000 would beat every branch it was given.", "That the chance nodes agree across stages, because the engine checks every later chance node against the ones above it."]'::jsonb, 1, 'The published allNegative case passes every check and recommends a branch worth -52.0000, because no walk-away was drawn and the engine never adds one.'),
  ('decision', 'beginner', 'final', null, 5, 'A Builder terminal was linked to a saved Monte Carlo run with an NPV mean of 420, and the run has since been revalued. What does the tree roll back with?', '["The revalued mean, because the Builder re-reads every linked run each time a rollback is requested from the explorer.", "The mean copied when the terminal was linked, until someone links it again.", "The revalued P90, the low case, because a linked terminal falls back to that end of its summary whenever the run behind it has changed.", "Nothing at all, because a stale link is refused with the message that the distribution payoff has no finite mean."]'::jsonb, 1, 'Linking stores a copy of the run''s mean, P90 and P10 at that moment and nothing re-reads the run, so the EKPAN tree stays at 105.0000 whatever the run now holds.'),
  ('decision', 'beginner', 'final', null, 6, 'Inside the EKPAN tree''s drill chance node the Marginal outcome carries 170.0000, although the develop payoff below it is 260.0000. Where does 170.0000 come from?', '["The chance node averages the marginal find''s Develop and Sell branches, because the later decision has not yet been made when the drill outcome is weighted.", "The EKPAN tree''s develop cost of 90.0000 is charged at the drill chance node after weighting, and 170.0000 is the figure the node shows once that charge is made.", "It is the sale at 140.0000 plus the share of the develop payoff the owner keeps, since a marginal find is split between the two later choices.", "On the EKPAN tree the marginal find is a decision; its best branch, Develop, is 260.0000 less its 90.0000 cost, and the chance node weights that branch value."]'::jsonb, 3, 'Weighting 260.0000 treats development as free and weighting 140.0000 forgets the owner would develop; either gives a drill node other than 160.0000, and the engine has nothing to refuse.'),
  ('decision', 'beginner', 'final', null, 7, 'A four level tree in the shape of deepAlternation has its deepest chance node rebuilt with three branches typed at 0.333333 each. What does the engine return for the root?', '["Nothing: that node is refused with its sum printed as 0.999999, and a refusal at any depth leaves no EMV anywhere in the tree.", "The root EMV, because 0.999999 sits exactly 1e-6 from 1 and the tolerance accepts a sum lying on its own edge.", "The root EMV with the deepest node rescaled so its three branches sum to 1, which restores the intended equal thirds before weighting.", "An EMV for the levels above the refused node, which enters its parent''s weighting at 0.0000 until the probabilities are retyped."]'::jsonb, 0, 'In binary the gap evaluates to 0.0000010000000000287557, just above 1e-6, so the node is refused, and depth hides nothing: the published sum of 0.200000 two levels down refuses a whole tree too.'),
  ('decision', 'beginner', 'final', null, 8, 'Refused at a printed sum of 0.999000 on a node of three equal outcomes, a reader adds the whole shortfall to the last branch and the tree is accepted. What has the fix done?', '["Nothing the engine would treat differently, because it rescales every accepted sum to exactly 1 before weighting and the shortfall is absorbed there.", "Restored the equal thirds, since a shortfall that small spread over one branch is below the precision the probabilities are printed to.", "Given the last outcome more weight than the other two, which were meant to be equal.", "Left the value unchanged, because the payoffs on three equal outcomes are symmetric and moving weight between them cannot move their average."]'::jsonb, 2, 'The engine checks a sum and never repairs one; typed at 0.3333333 each the thirds sum to 1.000000 and the node on payoffs of 30, 60 and 90 is worth 60.0000.'),
  ('decision', 'beginner', 'final', null, 9, 'The published chanceRootWithBranchCosts tree has a chance node at its root, with a cost of 2.0000 on calm and 8.0000 on storm. What do the Decision Tree Builder''s cards show?', '["Optimal EMV -3.0000, Chance root on the first move card, and N/A for the next best alternative and the decision advantage.", "Optimal EMV -8.6000, because the Builder totals a chance root''s costs and subtracts them once from the weighted children.", "Optimal EMV -3.0000 with calm as the recommended first move, since calm carries the larger probability of 0.600000 and the higher branch value.", "Optimal EMV 17.0000 for calm, with a decision advantage of 50.0000 over storm, read as if the chance root were a decision between them."]'::jsonb, 0, 'Each branch pays its own cost before weighting, 0.600000 x 17.0000 + 0.400000 x -33.0000 = -3.0000, and a chance root offers no move to recommend.'),
  ('decision', 'beginner', 'final', null, 10, 'Subtracting every cost on chanceRootWithBranchCosts once, after weighting, gives -8.6000 against the engine''s -3.0000. Where does the difference come from?', '["It weights each cost by the other branch''s probability, so the storm cost of 8.0000 is counted at 0.600000 instead of 0.400000.", "The hand figure charges the storm''s cost in the calm and the calm''s cost in the storm.", "It is the engine rounding each cost to four decimals before weighting, a step that a hand calculation carried at full precision avoids.", "It counts the chance root''s own cost twice, because the engine charges a root cost once and the hand calculation applies it on both branches."]'::jsonb, 1, 'A cost is paid only when its branch occurs: 2.0000 only in the calm and 8.0000 only in the storm, and -8.6000 is never refused because no engine ever sees a hand calculation.'),
  ('decision', 'beginner', 'final', null, 11, 'A reviewer rolls back deepAlternation with its two costs, 4.0000 on go and 6.0000 on push, gathered and taken off together at the root, and gets 3.0000. What went wrong?', '["Nothing went wrong, since costs are additive and the order in which a hand rollback subtracts them cannot change the value at the root.", "The push cost should have been left out, because once push carries its cost of 6.0000 the decision beneath up switches to hold instead.", "The costs should have come off after weighting at every level rather than at the root, which is what the engine does to reach 6.0000.", "The push cost was charged on the down branch too; paid only on up, weighted 0.500000, it costs the root half as much and the root is 6.0000."]'::jsonb, 3, 'Push is paid only under up: 0.500000 x 23.0000 + 0.500000 x -3.0000 = 10.0000, less 4.0000 on go is 6.0000; chanceRootWithBranchCosts shows the same error at -8.6000 against -3.0000.'),
  ('decision', 'beginner', 'final', null, 12, 'On the EKPAN tree, reading the linked success summary at its P50 of 390 keeps Drill, while reading it at its P90 of 185 hands the root to Farm out. What does that pair reveal that the rollback at the mean does not?', '["That the P50 is the payoff to type, because the switch sits below it and a middle case keeps the tree on the safe side of the choice.", "Nothing about the choice, since the engine refuses to value a terminal at any statistic of a summary other than its mean.", "The success payoff at which the EKPAN tree''s choice turns lies inside the summary''s spread, which the mean alone never shows.", "That the choice turns at the mean of 420 itself, because a linked payoff can flip a tree only when its mean is the value that moves."]'::jsonb, 2, 'On the EKPAN tree the drill branch is 22.7500 at a payoff of 185.0000 and 94.5000 at 390.0000, bracketing the farm-out''s 37.7500; at the mean the root reads 105.0000 and reports none of that spread.'),
  ('decision', 'beginner', 'final', null, 13, 'Read at its summary''s P90 of 185, the EKPAN tree''s root becomes 37.7500, exactly the farm-out branch value. Why exactly that number?', '["The EKPAN tree''s drill branch falls to 22.7500, below the farm-out, so the root takes the farm-out, whose value never depended on the drill''s success payoff.", "The engine floors a root at its next best alternative when the best branch collapses, so the EKPAN tree''s 37.7500 is a clamp and not a branch value.", "Reading a P90 lowers every success payoff in the tree to its low case, and the farm-out''s weighting happens to land on the same figure.", "The root averages Drill and Farm out when a linked payoff is read away from its mean, and on the EKPAN tree the two values meet at 37.7500."]'::jsonb, 0, 'On the EKPAN tree a decision node takes its largest branch value, 37.7500 against 22.7500 and 0.0000; the flip puts a risk preference where the engine expects a mean, and at the mean the root is 105.0000 with Drill.'),
  ('decision', 'beginner', 'final', null, 14, 'The Builder shows the EKPAN tree''s decision advantage as 67.2500 for Drill over Farm out, and a manager reads it as the extra money drilling will make. What is it?', '["The margin by which drilling beats the farm-out in every outcome, since a decision node compares its branches outcome by outcome before it chooses.", "The drill''s gain on its most likely outcome, since the card reads the difference between the two branches at the outcome carrying the largest probability.", "What the owner gives up by walking away, since the card sets the recommended move against the branch worth 0.0000 on the EKPAN tree.", "A difference of two averages on the EKPAN tree, 105.0000 less 37.7500; in the dry hole, with probability 0.500000, the drill leaves less than the farm-out."]'::jsonb, 3, 'On the EKPAN tree the next best alternative is 37.7500, so the advantage is 67.2500; in the dry hole the drill leaves -80.0000 against the farm-out''s 0.0000.'),
  ('decision', 'beginner', 'final', null, 15, 'At a success probability of 0.100000 the EKPAN tree''s root takes Farm out. What happens there to the onOptimalPath flag on the drill''s dry hole?', '["It stays true, since a dry hole worth -25.0000 is the outcome most worth planning for when success on the EKPAN tree is that unlikely.", "It reads false like every drill outcome, and the farm-out''s three outcomes read true, because the flags follow the branch the root takes.", "It stays true, because a flag records how likely an outcome is, and the EKPAN tree''s dry hole rises to 0.750000 at that success probability.", "Every outcome on both branches reads true, since at 0.100000 no branch of the EKPAN tree''s root clearly dominates the other two."]'::jsonb, 1, 'At success 0.100000 the EKPAN tree reads Drill -6.2500, Farm out 14.0000 and Walk away 0.0000, so Farm out is taken and nothing under Drill is reachable, however likely it is.'),
  ('decision', 'beginner', 'final', null, 16, 'The Builder''s cards for OKRIKA read Optimal EMV 87.0000 and Recommended first move Appraise. What do the other two cards read?', '["Next best alternative 183.6000 for Develop now, read off its development chance node before the 150.0000 cost is paid on the branch.", "Next best alternative 33.6000 for Develop now, because the card skips a sale, which is a terminal leading to no further node.", "Next best alternative 48.0000 for Sell now and a decision advantage of 39.0000, since Develop now is worth 33.6000 after its cost.", "Next best alternative 15.6000, since the card sets the appraisal against its own version with no option to sell."]'::jsonb, 2, 'Next best is the largest other root branch value: Develop now is 183.6000 less 150.0000 = 33.6000 and Sell now is 48.0000, so the advantage is 87.0000 less 48.0000 = 39.0000.'),
  ('decision', 'beginner', 'final', null, 17, 'On the published allNegative case the Builder names B with a decision advantage of 3.0000 over A. What does that advantage tell a reader?', '["Only that B loses 3.0000 less than A on average, and nothing about whether either should be taken.", "That B earns 3.0000 on average, since the card reports the winner''s margin above a zero floor.", "That B is the safer branch, because the advantage is worked out on the worst outcome of each branch rather than on their averages.", "That the engine found both branches negative, added a walk-away at 0.0000, and reported B''s margin over A as a fallback."]'::jsonb, 0, 'The engine returns EMV -52.0000 against -55.0000; it has no zero floor and never adds a walk-away, so the recommendation is an instruction to lose 52.0000 on average.'),
  ('decision', 'beginner', 'final', null, 18, 'On the EKPAN lottery Drill crosses Walk away at 0.179775 and that crossing never decides the first move, while on allNegative an undrawn walk-away would have decided it. What separates the two?', '["The lottery sweeps its success probability and allNegative holds its values fixed, and walking away can only win on a tree whose probabilities never move.", "The EKPAN lottery''s crossing lies within the tolerance of 1e-6 of the farm-out switch, so the engine reads walking away there as a tie and keeps Drill.", "allNegative lists its best branch second, and the tie rule lets a walk-away listed after it win where the lottery lists Walk away last.", "The EKPAN lottery''s farm-out pays 0.0000 at worst and beats walking away at every positive success probability; allNegative has no branch with a floor at zero."]'::jsonb, 3, 'On the EKPAN lottery Farm out beats both other actions below 0.228571, so the walk-away crossing sits in a region it can never win; on allNegative a walk-away at 0.0000 would beat B at -52.0000.'),
  ('decision', 'beginner', 'final', null, 19, 'On equalEmvTie the branches read A 30.0000, B 30.0000 and C 29.9990. A reviewer relists them as C, A, B. Which branch does the engine name?', '["C, because the branch listed first keeps the decision whenever the values agree to the four decimals they are printed to.", "B, because once C takes the first place in the listing, the tie between A and B passes to the later of the two equal branches.", "A, because A is strictly greater than C and B only equals A.", "C, since 29.9990 differs from 30.0000 by less than the probability tolerance of 1e-6 and the engine counts the two as a tie."]'::jsonb, 2, 'A later branch displaces the best only when strictly greater: A beats C''s 29.9990 and B at 30.0000 does not beat A, so the EMV stays 30.0000 and the name records the listing.'),
  ('decision', 'beginner', 'final', null, 20, 'On the EKPAN lottery at 0.228571, with its actions listed Drill, Farm out, Walk away, the engine names Farm out. What would it name with the list reordered as Farm out, Drill, Walk away?', '["Drill, because a choice at a crossing follows listing order, as on the published drillFarmOut tree at 0.200000.", "Farm out again, because there Farm out is larger by rounding residue and listing order decides only an exact tie.", "Drill, since with Farm out first the strictly greater comparison lets the next branch displace it by the EKPAN lottery''s residue of -7.11e-15.", "Neither, because the engine refuses a decision whose two leading branches print the same value, as the EKPAN lottery''s two do at 21.7143."]'::jsonb, 1, 'On the EKPAN lottery Drill less Farm out is -7.11e-15 in either order, so Drill is never strictly greater; on drillFarmOut the two are exactly 12.0000 and the first listed wins.'),
  ('decision', 'beginner', 'final', null, 21, 'A team draws EKPAN''s walk-away branch with a negative payoff equal to money already spent on the licence. What does that do to the tree?', '["Biases it against walking away, because money spent before the decision is spent on every branch alike and has been charged to one.", "Corrects it, since walking away forfeits the licence, and a branch that ignores a real loss overstates what walking away is worth.", "Nothing to the choice, because the rollback treats money spent before the root as sunk and restates it to zero before weighting.", "Makes the engine refuse it, because a terminal on a decision branch cannot carry a payoff below the costs on the branches beside it."]'::jsonb, 0, 'Walking away is worth 0.0000 and competes as a branch like any other, so charging it money already gone lowers it against branches that were never charged the same sum.'),
  ('decision', 'beginner', 'final', null, 22, 'Rolling back twoStageSequential, why can the test result chance node not be valued before the decision that follows a Good result?', '["The Test cost of 5.0000 has to come off first, and it sits below the chance node in the order drawn.", "A chance node weights terminals directly, and its Good branch has no terminal until the later decision is removed from the tree.", "The engine rolls back from the root outward, taking the root''s branches before the nodes beneath them so costs are paid in time order.", "Its Good branch is worth whatever that decision takes, which is unknown until Develop and Sell are compared."]'::jsonb, 3, 'Develop is 200.0000 less 50.0000 = 150.0000 against Sell at 80.0000; only then 0.400000 x 150.0000 + 0.600000 x 20.0000 = 72.0000, less 5.0000 = 67.0000.'),
  ('decision', 'beginner', 'final', null, 23, 'What does OKRIKA''s appraisal chance node weight on its Poor branch, and why not the 56.0000 of the development node beneath it?', '["56.0000, because a chance node weights the node beneath each outcome and the development cost is charged once, at the appraisal branch.", "The sale at 25.0000, because development after a poor result is 56.0000 less 150.0000 = -94.0000 and the decision takes the larger branch.", "-94.0000, since a company that has paid 18.0000 for the appraisal is committed to developing, and the sale is a fallback off the path.", "The average of 25.0000 and -94.0000, because the decision after a poor result has not been made when the appraisal node is weighted."]'::jsonb, 1, 'A decision hands its chance parent its maximum, so OKRIKA''s appraisal node is 0.400000 x 225.0000 + 0.600000 x 25.0000 = 105.0000, less 18.0000 = 87.0000.'),
  ('decision', 'beginner', 'final', null, 24, 'OKRIKA''s appraisal branch is 87.0000 with the option to sell after a poor result and 15.6000 without it. A memo calls the 71.4000 between them the value of the appraisal. What is it?', '["The value of the option to sell after a poor result, inside a branch that still pays the appraisal cost.", "The value of the uncertainty the appraisal removes, since both versions of the tree appraise and only the later sale differs between them.", "The appraisal''s margin over its best alternative, Sell now, which the Builder prints as the decision advantage for the root.", "The worth of the sale after a good result, which the appraisal unlocks and the tree without sales loses."]'::jsonb, 0, 'The value lives on the poor side, weighted 0.600000; after a good result the sale was never taken, and against Sell now the appraisal''s margin is 39.0000.'),
  ('decision', 'beginner', 'final', null, 25, 'OKRIKA''s stages agree: 0.400000 x 0.750000 + 0.600000 x 0.200000 = 0.420000, the large field chance for Develop now. What would the engine do with a tree whose stages disagreed?', '["Refuse the tree, naming the stage whose probabilities disagree in the same way it names a node whose sum is off.", "Rescale the later chance nodes so their weighted mixture matches the earlier chance before it takes any maximum.", "Roll it back just the same, with no warning.", "Accept it only while the disagreement stays inside the tolerance of 1e-6 it applies to the sum at every chance node."]'::jsonb, 2, 'The engine has no link between chance nodes beyond the tree as drawn; it checks that each node''s probabilities sum to 1 within 1e-6 and nothing about how 0.420000 relates to the stages.'),
  ('decision', 'beginner', 'final', null, 26, 'Which of OKRIKA''s two later sales can be deleted without changing any number the rollback returns?', '["The sale after a poor appraisal, since at 25.0000 it is the smallest payoff in the appraisal subtree and so cannot move a maximum.", "Either one, because the appraisal is valued by what it reveals, and deleting a later branch leaves what it reveals unchanged.", "Neither, because every branch in a subtree whose first branch is taken is on the optimal path and carries part of its value.", "The sale after a good appraisal, which reads false and was never taken; the sale after a poor one reads true and carries 71.4000 of the branch."]'::jsonb, 3, 'Removing a later choice is safe only where it was never taken: without the poor side sale the appraisal falls from 87.0000 to 15.6000 and the root sells now at 48.0000.'),
  ('decision', 'beginner', 'final', null, 27, 'Without its later sales, OKRIKA''s appraisal chance node is 33.6000, exactly the value of Develop now. What does that coincidence show?', '["That the development chance nodes after the appraisal count the 0.420000 chance twice, so the tree values the same field on two branches.", "An appraisal that cannot change the action is the same development delayed, worth less than acting now by exactly its cost of 18.0000.", "That the appraisal removes no uncertainty, because a result known in advance collapses into the development it would have predicted.", "That the development cost is paid twice when appraising, once with the appraisal and once after it, so the two branches net to the same."]'::jsonb, 1, '0.400000 x 225.0000 + 0.600000 x -94.0000 = 33.6000, and less 18.0000 the branch is 15.6000; information of any kind is worth something only when it can change a choice.'),
  ('decision', 'beginner', 'final', null, 28, 'A reviewer reads deepAlternation''s optimal path as the forecast go, up, push, win. Which branches does the engine flag false?', '["hold and stop, and nothing else.", "down and lose, the two outcomes that pay less than the branch above them, along with hold and stop.", "stop, hold and down, since the down outcome leads to no later decision and so drops out of the plan.", "stop alone, because a branch below a taken branch is always on the path whether or not it wins its own decision."]'::jsonb, 0, 'A chance node picks nothing, so up, down, win and lose all stay on the path; push at 23.0000 beats hold at 12.0000 and go at 6.0000 beats stop at 1.0000.'),
  ('decision', 'beginner', 'final', null, 29, 'Sweeping the EKPAN tree, an analyst raises success to 0.400000 and leaves the marginal find at 0.150000 and the dry hole at 0.500000. What comes back for that row?', '["A row with success weighted at 0.400000 and the other two outcomes scaled down so the drill chance node still sums to 1.", "A row valued with the surplus probability ignored, since the engine caps a chance node''s sum at 1 before it weights the branches.", "A refusal, because the drill chance node no longer sums to 1 within 1e-6, and no EMV at all.", "The EKPAN lottery''s 98.0000 at 0.400000, since a swept tree takes its row values from the two outcome model of the same prospect."]'::jsonb, 2, 'When success rises the dry hole must fall by the same amount, as at 0.100000 where the EKPAN tree''s dry hole takes 0.750000; the engine checks sums and never rescales, and quoting the EKPAN lottery''s 98.0000 mixes the two models.'),
  ('decision', 'beginner', 'final', null, 30, 'Asked for the success probability at which the EKPAN lottery''s first move changes, a reader quotes 0.250000, the first sweep row where Drill wins. What should the answer be?', '["0.250000, because the engine evaluates probabilities only on its sweep grid and a switch between two rows has no meaning to it.", "0.179775, where the EKPAN lottery''s Drill first stops losing money against walking away, which is the move that changes first on the lottery.", "0.200000, the EKPAN lottery''s last Farm out row, since a switch is reported at the last probability where the earlier action still holds.", "0.228571, solved from the EKPAN lottery''s lines Drill = 445 p - 80 and Farm out = 95 p, a crossing the sweep can bracket and cannot place."]'::jsonb, 3, 'On the EKPAN lottery 350 p = 80 gives 80 / 350 = 0.228571; quoting 0.250000 overstates the probability the drill needs, and the engine never returns a switch point at all.'),
  ('decision', 'beginner', 'final', null, 31, 'A draft of the EKPAN lottery leaves the farm-out off because its terms are not agreed. Where does that draft put its switch?', '["At the EKPAN lottery''s 0.228571 still, because a switch belongs to the drill''s own line and not to the branches that happen to be drawn beside it.", "At 0.179775, where the EKPAN lottery''s Drill crosses Walk away, misplaced by the whole width of the farm-out region.", "At 0.200000, the first EKPAN lottery row where Drill is positive, since without a farm-out the draft has no crossing left to solve.", "Nowhere, since the engine refuses to sweep a probability through a decision node that has fewer than three branches."]'::jsonb, 1, 'With only the EKPAN lottery''s Drill = 445 p - 80 against 0.0000 the draft walks below 80 / 445 and drills above it, while with the farm-out drawn Farm out wins every probability up to 0.228571.'),
  ('decision', 'beginner', 'final', null, 32, 'A geologist cannot say whether the EKPAN lottery''s success chance is 0.200000 or 0.250000. What can the engine do with that doubt?', '["Take it as a distribution on the branch probability, which the rollback reduces to its mean just as it reduces a linked Monte Carlo payoff summary.", "Report the average of the two rows'' EMVs, which is the value the engine returns for a branch whose probability is typed as a range.", "Nothing directly: it takes one probability per branch, so the doubt means separate rollbacks, and here they straddle the switch and disagree.", "Refuse the tree, since a probability typed as a range fails the check that each branch lies between 0 and 1."]'::jsonb, 2, 'On the EKPAN lottery Farm out leads 19.0000 to 9.0000 at 0.200000 and Drill leads 31.2500 to 23.7500 at 0.250000, either side of 0.228571; only a payoff may carry a summary that enters at its mean.'),
  ('decision', 'beginner', 'final', null, 33, 'A slide reads: EKPAN is worth 75.7500 million USD to drill and loses money with probability 0.500000. What is wrong with it?', '["It mixes two models: 75.7500 is the EKPAN lottery''s drill action, which loses with probability 0.650000, and 0.500000 belongs to the EKPAN tree, whose drill branch is 105.0000.", "Nothing, because both numbers come from the EKPAN lottery at its stated success probability of 0.350000.", "The loss chance should be 0.350000, the EKPAN lottery''s success probability, since a drill loses whenever the prospect is short of a clear success.", "The value should be 160.0000, the EKPAN tree''s drill node, because a loss chance is stated before the drill cost is paid."]'::jsonb, 0, 'Mixing the two models is exactly the error: the EKPAN tree has a marginal find at 0.150000 and a dry hole at 0.500000, while the EKPAN lottery folds the marginal find into a dry hole at 0.650000.'),
  ('decision', 'beginner', 'final', null, 34, 'About the published drillFarmOut sweep, Ada writes "drill from 0.200000" and Bola writes "farm out up to 0.200000". Whose reading is honest?', '["Ada''s, because the engine names Drill at 0.200000 and the recommendation there is the tree''s own answer to the question.", "Bola''s, because Farm out leads on every row below 0.200000 and a tie is resolved toward the action that held before it.", "Ada''s, since the tie at 0.200000 is float residue of the kind the EKPAN lottery shows at its crossing, and Drill is larger by it.", "Neither alone: at 0.200000 both branches are worth 12.0000 and the owner is indifferent, and the engine''s Drill there is listing order."]'::jsonb, 3, 'The engine keeps the first branch listed on an exact tie and has no tie flag; the advantage at 0.200000 is 0.0000, and above it Drill leads, 27.5000 to 15.0000 at 0.250000.'),
  ('decision', 'beginner', 'final', null, 35, 'On the EKPAN lottery at 0.350000 the drill loses money with probability 0.650000, and a reviewer concludes the rollback''s Drill must be an error. What is the right response?', '["The reviewer is right, because the engine refuses to recommend an action whose most likely outcome is a loss and this one has slipped through.", "The loss chance does not overturn expected money: the EKPAN lottery''s Drill at 75.7500 still beats Farm out at 33.2500, and a company that cannot absorb a loss of 80.0000 holds a preference the engine cannot express.", "The reviewer is right, since at 0.650000 the EKPAN lottery drill''s expected value is -80.0000 and the table''s 75.7500 is the value on success.", "The loss chance is beside the point, because 0.650000 is the EKPAN tree''s dry hole probability and belongs to a different model."]'::jsonb, 1, 'Calling 0.650000 the EKPAN tree''s figure mixes the two models, since it is the EKPAN lottery''s own dry hole and the EKPAN tree''s is 0.500000; on the lottery 0.350000 x 365.0000 + 0.650000 x -80.0000 = 75.7500; the rollback maximises expected money and reports no chance of loss or worst case.'),
  ('decision', 'beginner', 'final', null, 36, 'The expected value of perfect information on the EKPAN lottery is 52.0000 at the stated 0.350000 and 61.7143 at 0.228571. Why is it larger at the second probability?', '["Because at 0.228571 the EKPAN lottery''s drill is worth more than at 0.350000, and perfect information is a fixed share of the best action''s value.", "Because a lower success probability makes the dry hole likelier, and perfect information is worth most wherever a loss is likeliest.", "0.228571 is the drill against farm-out switch, where the choice made without information is most fragile and knowing the outcome first is worth most.", "Because the EKPAN lottery''s residue of -7.11e-15 at the crossing is added to the value with information, inflating it at that one point."]'::jsonb, 2, 'On the EKPAN lottery at 0.350000 knowing the outcome gives 0.350000 x 365.0000 + 0.650000 x 0.0000 = 127.7500 against 75.7500, a difference of 52.0000; the peak of 61.7143 sits on the switch this tier solves.'),
  ('decision', 'beginner', 'final', null, 37, 'The VOI Analyzer''s second action is Do Not, with every payoff 0. Set beside the EKPAN lottery''s three actions, which one is it, and what does offering it instead of the farm-out do?', '["It is Walk away, which the farm-out dominates, so the Analyzer keeps the alternative that is never best and drops the one that can be.", "It is the farm-out with its payoffs cleared, so the Analyzer still values the same three actions, with one of them simply set to 0.0000.", "It is Drill at no cost, the Analyzer''s way of pricing the decision without the EKPAN lottery''s drill cost of 55.0000.", "It is a placeholder the Analyzer ignores, so the survey is valued on Drill alone as if the owner had no alternative."]'::jsonb, 0, 'On the EKPAN lottery Farm out pays 95 p, positive whenever success is possible, so walking away never wins; the Analyzer''s gross value of 19.84 is the two action number, against 24.8250 with the farm-out.'),
  ('decision', 'beginner', 'final', null, 38, 'At a survey cost of exactly 24.8250, the two root branches of the information tree built on the EKPAN lottery tie, and the engine recommends acquiring the survey. What decides that?', '["The survey''s positive gross value, since the EKPAN lottery''s survey, worth 24.8250 before its cost, is always worth acquiring at that same price.", "Float residue at the crossing, as at the EKPAN lottery''s switch of 0.228571, where the survey branch comes out larger in its last binary digits.", "A rule breaking ties toward the branch that carries more information, which the information tree applies before it compares values.", "The tie rule: acquiring is listed first, and a later branch replaces it only when strictly greater."]'::jsonb, 3, 'The price that makes information neutral is its gross value, 24.8250 on the EKPAN lottery; at that cost the branches are equal and the name is listing order, as on drillFarmOut at 0.200000.'),
  ('decision', 'beginner', 'final', null, 39, 'Before its repair the VOI Analyzer printed a gross value of information of -15.00 for IRRI, whose indicators were both typed 20 / 80. What does the repaired Analyzer do there, and why?', '["Prints 0.00 in place of -15.00, clamping the value at the floor information derived by Bayes never falls below.", "Withholds the value of information, because the typed numbers imply a success chance that contradicts the stated one.", "Prints -15.00 as before beside a warning, since a negative value correctly tells the user that the survey is not worth buying.", "Refuses the form with a message naming the sum in percent, because an indicator typed 20 / 80 is not a distribution."]'::jsonb, 1, 'Both indicators at 20 / 80 imply a success chance of 0.200000 against 0.3 stated; the repaired Analyzer keeps EMV without information at 15.00 and EVPI at 63.00 and withholds the rest.'),
  ('decision', 'beginner', 'final', null, 40, 'Checking a hand rollback against the explorer, a learner has 375.0000 for OKRIKA''s good appraisal branch where the engine has 225.0000. What does the size of the gap point to?', '["A probability typed wrongly in the development chance node, since moving weight between 0.750000 and 0.250000 shifts the value by that much.", "The sale at 95.0000 taken in place of development, which leaves the good branch short by the difference between the two figures.", "A node value read where the branch value belongs: the gap is exactly the 150.0000 development cost on the branch into that node.", "Payoffs the learner left undiscounted, which the engine discounts on the way back from 520.0000 toward the appraisal node."]'::jsonb, 2, 'A value read off a node where the branch was asked for is wrong by exactly the branch cost; the Builder''s drawing invites it by labelling a node before that cost, as with the EKPAN tree''s drill node at 160.'),
  ('decision', 'beginner', 'final', null, 41, 'OKRIKA''s appraisal cost of 18.0000 is paid today and its development cost of 150.0000 only after a result is known. What must hold for the root''s 87.0000 to mean anything?', '["Every cost and payoff must already be discounted to the date of the root decision, because the rollback takes them at face value.", "The development cost must be typed undiscounted, since the engine discounts each deeper level of the tree by one stage before weighting it.", "Nothing about timing, because costs paid in different years cancel out of any comparison between branches that contain them.", "The appraisal cost must be charged at the root instead of on its branch, so that money paid today stays apart from later money."]'::jsonb, 0, 'The engine has no rate and no date in any node, so a tree is only as well discounted as its typed numbers; the EKPAN tree''s develop cost of 90.0000 after a marginal find needs the same care.'),
  ('decision', 'beginner', 'final', null, 42, 'A chance node has one branch typed at a probability of 1.5. Which check stops it, and what comes back?', '["The sum check, reporting a sum above 1 against an expected 1, since the engine tests the range of probabilities only on their totals.", "No check: the engine clips the branch to 1 and sets the others to 0, so the node rolls back to that one branch''s value.", "The branch count check, reporting that the node needs at least one branch, because a probability above 1 voids the branch that carries it.", "The range check on that branch, before any sum is taken, and no EMV."]'::jsonb, 3, 'The published message reads Branch "a" needs a probability between 0 and 1 (at node "bad"); the engine checks and reports and never repairs, and a sum of 1.2 is refused as well.');
